// L'Île Folle-Aiguille · what became of them. The endings' titles, the epilogue lines (the others: the island, the
// coast, the people met on the way, each line read from what the reader did), and the fates of the ten people the
// story follows: the first fate whose condition holds, the last one by default; `dens` names the dénouements a fate
// can follow (none: all).
var BARON = { not: { has: "xs:baron_mort" } };
var RENTRE = ["baron", "livre", "ile", "chevalier", "dagrel", "corde"];
module.exports = {
  passages: {},
  extras: {
    endings: {
      baron: { title: "Morlenc reste aux mêmes" }, livre: { title: "Le livre devant le Conseil" }, ile: { title: "L'argent de l'île" },
      mutins: { title: "Le pavillon noir" }, chevalier: { title: "Les cales vides" }, naufrage: { title: "La colonie" },
      dagrel: { title: "Le capitaine reprend la mer" }, corde: { title: "La Croix-des-Marées" },
    },
    epilogue: [
      { if: { has: "rose:recue" }, text: "La rose sans aiguille clouée au volet de la chambre de la mer, au Fanal, y reste des années. Zélie refuse qu'on l'enlève. Elle dit que ça porte malheur. Elle a raison, mais c'est déjà fait." },
      { if: { has: "larrouy:mort" }, text: "Ignace Larrouy, le Gabier, repose au cimetière de la Pointe-aux-Corneilles, sous une croix de bois que l'abbé Morisseau a bénie à contrecœur. Quelqu'un y pose, chaque année, à la Toussaint, trois piastres de la Miséricorde. On ne sait pas qui. On ne les vole jamais." },
      { if: { any: [{ has: "brousse:message" }, { has: "brousse:repris" }] }, text: "Nathanaël Brousse, le numéro neuf de Brisegrève, gratte toujours le mur de son cachot. Il a creusé, en vingt ans, un trou de la profondeur d'un doigt. Il dit qu'il a le temps." },
      { if: { any: [{ has: "brousse:evade" }, { has: "brousse:libere" }, { has: "brousse:baron" }] }, text: "Nathanaël Brousse, le numéro neuf, sorti de son cachot de Brisegrève, ne retourne jamais à terre. Il s'engage comme pilote sur tous les navires qui veulent bien d'un vieillard, et corrige les aiguilles des autres avec un mépris affectueux." },
      { if: { all: [{ has: "brousse:secret" }, { not: { any: [{ has: "brousse:evade" }, { has: "brousse:libere" }, { has: "brousse:baron" }] } }] }, text: "Le numéro neuf a donné son secret, à travers un mur, contre une promesse. Il attend qu'on la tienne. Il a l'habitude d'attendre." },
      { if: { has: "vauclair:sauve" }, text: "Le chirurgien Vauclair s'installe à Varnèse, à deux rues du cabinet de Victorine Davrigny. Ils se disputent les malades, et se les envoient. Il ne touche plus à sa teinture. Il en garde un flacon dans un tiroir, pour se souvenir." },
      { if: { has: "vauclair:livre" }, text: "Le chirurgien Vauclair, livré aux fers à bord de la Cormorane, est jugé à Morlenc pour un crime qu'il a commis sous un autre visage. Il se défend mal. Il ne sait plus lequel des deux a fait quoi." },
      { if: { has: "vauclair:gris" }, text: "L'homme gris qu'est devenu le chirurgien Vauclair erre encore, dit-on, dans les ruelles de la Basse-Fosse, la nuit. On ferme les volets quand on l'entend rire." },
      { if: { has: "correction:parchemin" }, text: "Le parchemin du Gabier, avec sa phrase à l'encre sympathique, « tirez trois quarts au couchant, et partez de la pierre qui sonne », finit encadré au mur de la salle du Fanal, à côté du baromètre. Les clients croient que c'est une devinette. Ils n'ont pas tort." },
      { if: { all: [{ has: "morlenc:diseuse" }, { has: "dagrel:demasque" }] }, text: "Une vieille diseuse de la foire aux harengs t'avait annoncé un mort qui marche, qui mange, qui parle, sous un autre nom. Tu repasses devant sa roulotte, l'automne suivant. Elle te regarde, et te demande deux sous, sans rien dire de plus. Tu les lui donnes." },
      { if: { has: "morlenc:presse_averti" }, text: "Le vieux Pellerin raconte dans toutes les tavernes de la Basse-Fosse comment un mousse de la Cormorane a vidé la Truie-qui-file sous le nez de la presse. Il ajoute chaque fois un enseigne de plus. Il en est à quatre." },
      { if: { has: "morlenc:presse_cache" }, text: "Il t'arrive encore, la nuit, d'entendre des pas en cadence dans une rue vide, et de te plaquer contre une porte avant de savoir pourquoi." },
      { if: { has: "morlenc:faculte_parle" }, text: "Un étudiant maigre de la Faculté de Morlenc publie, trois ans plus tard, un mémoire sur la fièvre des accouchées et le lavage des mains, appuyé sur trois cent douze observations recueillies à Varnèse. La Faculté le refuse. Les sages-femmes le recopient à la main." },
      { if: { has: "morlenc:faculte_tue" }, text: "Victorine Davrigny envoie un jour à la Faculté de Morlenc un mémoire anonyme sur la fièvre des accouchées, appuyé sur trois cent douze observations. Personne ne le lit. Elle le savait. Elle l'a envoyé pour la honte qu'elle avait eue, au dernier rang, et qui est enfin partie." },
      { if: { has: "victorine:alliance" }, text: "Sur la dalle d'Hector Davrigny, au cimetière des Hollandes, il n'y a jamais eu de bague. Les corbeaux de Morlenc sont connus pour leur goût de l'or." },
      { if: { has: "morlenc:jumeaux" }, text: "Rue des Cordiers, au cinquième, sous les toits, une petite fille s'appelle Victorinne, avec deux n, par la faute d'un commis. Elle a un frère jumeau qui la bat à la course et qui doit la vie à un pied trouvé dans le noir." },
      { if: { has: "morlenc:jumeau_mort" }, text: "Rue des Cordiers, une petite fille crie pour deux, depuis sa naissance. Sa mère dit que c'est pour son frère. Victorine Davrigny lui envoie, chaque année, une poupée, sans signer." },
      { if: { has: "bord:bapteme_refus" }, text: "Sur un morceau de toile à voile, encadré au mur d'une chambre, un brevet en latin de cuisine porte la mention : « Hérétique repenti, quatre immersions. » C'est le seul diplôme que {joueur} ait jamais accroché." },
      { if: { has: "bord:bapteme_rit" }, text: "Le brevet du Bonhomme Tropique, signé d'une croix et d'un poisson, finit glissé entre les pages d'un livre, où on le retrouve des années plus tard, taché de goudron, avec un rire qui vient avant le souvenir." },
      { if: { has: "bord:requin" }, text: "Il arrive à {joueur} de regarder l'heure à une montre et de penser, sans le vouloir, à un fils qui devait revenir à quatre heures moins dix." },
      { if: { has: "bord:loch" }, text: "Toute sa vie, {joueur} compte sans y penser : les pas, les marches, les secondes entre l'éclair et le tonnerre. Une ligne à nœuds file quelque part au fond de sa tête, et dit toujours la vérité." },
      { if: { has: "bord:feux" }, text: "Personne, au Fanal, n'a jamais cru à l'histoire de la mer qui brûle. {joueur} ne l'a jamais racontée deux fois." },
      { if: { has: "bord:jambe_sauvee" }, text: "Mathurin Le Gall, gabier, remonte dans la mâture de la Cormorane avec une jambe plus courte de deux pouces. Il dit que c'est la plus belle jambe du bord, parce qu'une femme a tiré dessus comme sur une drisse." },
      { if: { has: "bord:jambe_coupee" }, text: "Mathurin Le Gall tient une échoppe de cordier sur le Quai des Hollandes, avec une jambe de bois taillée dans un espar de la Cormorane. Il n'en veut à personne. C'est ce qu'il y a de plus difficile à supporter." },
      { if: { has: "ribaud:secret" }, text: "Dans le coffre de la capitaine Ribaud, il y a toujours, depuis ce voyage, une racine de gingembre enveloppée dans un mouchoir. Elle n'en parle à personne. L'équipage non plus." },
      { if: { has: "bord:rats_chat" }, text: "Linné, l'angora blanc du professeur Gaudrémont, chasse jusqu'à sa mort dans les caves de l'Académie de Morlenc, où il décime une colonie de rats que trois générations de savants avaient décrite sans oser y toucher." },
      { if: { has: "bord:rats_poison" }, text: "Les marins qui embarquent sur la Cormorane, des années plus tard, jurent qu'elle sent encore, par temps chaud, quelque chose de doux et de mort, au fond de la cale. Ils appellent cette odeur la médecine." },
      { if: { has: "bord:bapteme_paye" }, text: "{joueur} n'a jamais été plongé{joueur:e} dans la baille du Bonhomme Tropique. Il en reste une goutte d'eau de mer, tombée d'un trident sur une tête, et l'envie, à chaque voyage, de payer moins cher et de rire davantage." },
      { if: { has: "fargue:laudanum" }, text: "Lucien Fargue n'a jamais avoué à personne le secret du meilleur cochon de sa vie. Il le garde pour lui, avec quelques autres, dans le même tiroir." },
      { if: { all: [{ has: "fargue:festin" }, { not: { has: "fargue:laudanum" } }] }, text: "Les survivants du camp de la plage parlent encore, dans les tavernes de Morlenc, d'un cochon cuit sous le sable par la Chanson, une nuit de Folle-Aiguille. À chaque récit, le cochon grossit. Il a maintenant la taille d'un bœuf." },
      { if: { has: "fargue:enterre" }, text: "Sur la plage de Folle-Aiguille, un aviron cassé a longtemps marqué une tombe. La marée l'a emporté. La tombe, elle, est toujours là, sous le sable, avec ou sans nom." },
      { if: { has: "gabet:deserte" }, text: "Térence Gabet, noyé en pêchant la langouste d'après le rapport du maître-coq, rentre à Morlenc par un autre navire, six mois plus tard, et paie ses dettes avec sa paie de matelot. Sa fille ne lui demande jamais d'où il revient." },
      { if: { has: "gabet:retenu" }, text: "Térence Gabet n'a jamais tenu une pelle sur Folle-Aiguille. Il a épluché des racines pendant tout le siège. Il dit, plus tard, que c'est la chose la plus utile qu'il ait jamais faite, et il le pense." },
      { if: { has: "chapelle:soulier" }, text: "Victorine Davrigny garde dans son carnet, à une page qu'elle n'ouvre jamais, la liste de quarante-trois squelettes. La dernière ligne dit : « Un soulier rouge. » Le baron Clavières, dit-on, fait dire une messe chaque année pour une femme et un enfant dont il ignore les noms." },
      { if: { all: [{ has: "chapelle:crypte" }, { not: { has: "chapelle:soulier" } }] }, text: "Sous le chœur de la Miséricorde, une dalle scellée au mortier de chaux recouvre quarante-trois morts. Les mouettes, qui nichent maintenant dans le clocher, sont les seules à marcher dessus." },
      { if: { has: "chapelle:source_nuit" }, text: "Victorine Davrigny n'entend jamais une complainte de cuisine sans penser à une source, la nuit, et à un homme qui chantait pour qu'on ne l'entende pas." },
      { if: { has: "ile:perroquets" }, text: "Dans le bois mort de Folle-Aiguille, les perroquets gris parlent toujours avec les voix de la colonie. Un savant de Morlenc vient un jour noter leurs paroles, mot pour mot, et publie la liste. On y trouve, entre un psaume et un alphabet, une voix qui dit : « Ouvrez. »" },
      { if: { has: "fargue:souvenir_ecrit" }, text: "Au fond d'un sac de marin, sous des chemises, deux pages pliées en quatre racontent une plage, une lune, un habit et une main levée. Elles sont adressées à une jeune fille qui ne les a jamais lues." },
      { if: { has: "fargue:souvenir_brule" }, text: "Une seule tête au monde garde le souvenir exact d'une plage, d'une lune, et d'un capitaine qui salue. Elle le garde bien. Elle le garde trop bien." },
      { if: { has: "fargue:malandain_promis" }, text: "Malandain a eu sa date. Il l'a tenue. On ne lui en a jamais donné d'autre." },
      { if: { has: "fargue:malandain_attend" }, text: "Lucien Fargue a fait attendre Malandain quelques jours de plus, dans les Sargues. Il ne saura jamais combien de vies ces quelques jours ont coûté ou épargné. Il les compte parfois, la nuit, sur trois doigts." },
      { if: { has: "fargue:lagadec" }, text: "Isidore Lagadec, le Hareng, ne rêve plus de la chapelle. Il rêve d'une écuelle de soupe, dans une cambuse, à minuit, et d'une voix qui lui proposait de partir." },
      { if: { has: "fargue:choucroute" }, text: "La médecin Davrigny recommande la choucroute à tous les capitaines de Morlenc. Quand on lui demande d'où elle tient la recette, elle répond : d'un cuisinier qui gardait toujours quelque chose." },
      { if: { item: "ambre_gris" }, text: "Une masse d'ambre gris, gardée au sec dans une boîte de fer, finit chez un parfumeur de la Haute-Ville de Morlenc, qui la paie son poids d'or et en tire, l'année suivante, une eau qui sent la rose et, très loin, la mer chaude." },
      { if: { all: [{ has: "xo:ligne_coupee" }, { not: { has: "xo:homme_perdu" } }] }, text: "À Kerverzot, un garçon aux cheveux de paille boite d'une cheville et raconte qu'on lui a sauvé la vie d'un coup de hachette, en sacrifiant la plus belle baleine de la saison. Les vieux baleiniers trouvent l'échange discutable. Sa mère, non." },
      { if: { has: "xo:homme_perdu" }, text: "À Kerverzot, on grave sur la pierre des noyés un nom de plus : Yann Le Bris, dix-sept ans. La pierre est longue. On y a laissé de la place." },
      { if: { has: "xo:certifie" }, text: "Le capitaine Corentin Le Moal finit ses jours à Kerverzot, sur un banc face à la mer, avec une longue-vue qu'on ne lui a jamais reprise. Un certificat signé d'une main de femme l'a ramené chez lui. Il ne l'a jamais pardonné, et il s'en félicite en secret, certains soirs." },
      { if: { has: "xo:refuse" }, text: "La Constance, de Kerverzot, n'est jamais rentrée. On dit qu'un baleinier noir de suie croise encore dans les herbes des Sargues, à la poursuite d'une ombre à tête grise. On le dit dans tous les ports. Personne ne l'a vu." },
      { if: { has: "xo:dort" }, text: "Le capitaine Le Moal rentre à Kerverzot et dort, la nuit, d'un sommeil léger, où un garçon de onze ans lui montre un crabe sur la grève. Il ne chasse plus. Il garde, au mur, une seule dent gravée." },
      { if: { has: "xu:cloche" }, text: "La cloche de la Miséricorde, tirée d'une grotte de la mer par un enfant et trois barriques, sonne de nouveau sur Folle-Aiguille. On l'a pendue à une branche maîtresse, faute de clocher. Elle sonne pour les vivants. C'est écrit dessus." },
      { if: { has: "xu:pieuvre_tuee" }, text: "Toute sa vie, {joueur} porte sur un bras une rangée de petites cicatrices rondes, régulières, comme des baisers. On demande souvent d'où elles viennent. La réponse, une grotte et une bête à l'œil doré, ne convainc personne." },
      { if: { has: "xu:sauve" }, text: "Dans une grotte de l'est, au pied de la falaise, plus rien ne garde le fond. Un vieil homme y a rompu un arrangement de vingt et un ans pour sauver un enfant. Il dit que c'est le seul contrat qu'il ait jamais rompu sans le regretter." },
      { if: { has: "victorine:sabine" }, text: "À Varnèse, Madame Saint-Aubert a eu une indigestion de moules, un soir de novembre, et la médecin est venue en pleine nuit. Elle va au sermon de dix heures avec ses trois enfants, qui grandissent. Le juge de paix ne s'est aperçu de rien. Il ne s'aperçoit jamais de rien ; c'est ce qui fait de lui un si bon juge." },
      { if: { has: "victorine:sabine_refus" }, text: "À Varnèse, Madame Saint-Aubert a mis au monde, au printemps, une quatrième fille, avec une sage-femme renvoyée à ses prières et le chirurgien de la garnison, que la médecin avait instruit par lettre avant de partir. Elle a failli mourir. Elle ne l'a pas fait. Elle a appelé la petite Victorine, sans en dire la raison à son mari, qui l'a trouvée très chrétienne." },
      { if: { has: "victorine:laudanum_jete" }, text: "Dans la cave de Varnèse, sous les bouquets de pavot, une fiole propre, sans étiquette, contient de l'eau de mélisse pour les nerfs de Madame la mairesse, qui la trouve souveraine." },
      { if: { has: "victorine:jobic" }, text: "Jobic Le Goff braconne toujours dans les bois de la Garenne. Il boite un peu, les jours de pluie, et raconte à qui veut l'entendre qu'il a eu, une nuit, les fesses soignées par la femme la plus savante du Ponant, qui est partie pour les îles avec un trésor et un banquier, dans cet ordre." },
      { if: { has: "guivarch:lettre_vraie" }, text: "Rue des Cordiers, à Morlenc, une vieille femme a reçu quarante livres et quatre lignes d'un homme parti il y a trente-quatre ans. Elle a ri, puis elle a pleuré, puis elle a acheté une paire de draps. Elle dit qu'il n'a jamais su écrire, et qu'il lui a écrit la plus belle lettre du monde." },
      { if: { has: "guivarch:lettre_belle" }, text: "Rue des Cordiers, à Morlenc, une vieille femme a reçu trois pages d'un homme parti il y a trente-quatre ans. Elle les lit le soir, à la fenêtre, à côté d'un pot de basilic. Il y a une phrase qu'elle ne lit jamais à voix haute. Les voisins, parfois, l'entendent rire, et ne tapent plus au mur." },
      { if: { all: [{ has: "lemerle:yeux_secret" }, { marin: "lemerle", is: ["loyal", "hesitant"] }] }, text: "Annick Lemerle a fait abaisser sa cataracte à l'aiguille par un vieil homme de la rue des Lunetiers, à Morlenc. Une fois sur deux, on y voit après. Elle voit Rigel. Elle a envoyé à Varnèse un hareng fumé, sans un mot, ce qui chez elle est une lettre d'amour." },
      { if: { all: [{ has: "lemerle:yeux_dit" }, { marin: "lemerle", is: ["loyal", "hesitant"] }] }, text: "Annick Lemerle a quitté la mer au retour. Elle vend du hareng sur le quai de Morlenc, et elle connaît le vent du jour mieux que les pilotes. Quand on lui parle de médecins, elle crache par terre." },
      { if: { has: "xz:aveu_ecrit" }, text: "Sur le registre de la Prévôté de Morlenc, en marge d'une pendaison vieille de dix-neuf ans, un greffier a écrit à l'encre rouge, sur l'ordre exprès du Conseil : *Innocent.* La mère de Corentin Le Floch était morte. Une voisine de la rue des Tonneliers a porté le papier au cimetière et l'a lu à voix haute, devant une tombe sans nom, au cas où." },
      { if: { has: "xz:absous" }, text: "Le nom de Corentin Le Floch, pendu à la Croix-des-Marées pour un crime qu'il n'a pas commis, reste au registre de la Prévôté, à la colonne des coupables. Une seule personne au monde sait qu'il n'a rien à y faire. Elle y pense, parfois, en passant devant des églises." },
      { if: { has: "victorine:testaments" }, text: "Les testaments dictés dans la nef de la Miséricorde dorment dans la trousse de la médecin, pliés en quatre. Les vivants viennent les reprendre un à un, un peu honteux, comme on reprend un parapluie oublié chez une dame. Elle ne les leur rend jamais sans les avoir relus devant eux, à voix haute." },
      { if: { has: "victorine:ecorce_machee" }, text: "Victorine Davrigny n'a jamais retrouvé la couleur des yeux d'Hector. Elle a remis le portrait à l'endroit, au mur de son bureau, pour vérifier. Le peintre les a faits gris. Elle est presque sûre qu'il s'est trompé." },
      { if: { has: "victorine:ecorce_rendue" }, text: "Victorine Davrigny se rappelle tout. C'est fatigant. Elle le recommande." },
      { if: { has: "xw:enlise_sauve" }, text: "Un matelot de la Désinvolte, vingt ans, une dent en moins, raconte dans les ports du Couchant qu'un enfant l'a tiré d'une vase qui l'avalait, en lui apprenant à faire la planche dans la boue. Personne ne le croit. Il fait la démonstration, quand il a bu, dans les flaques." },
      { if: { has: "xw:enlise_laisse" }, text: "Il t'arrive de rêver d'une mangrove, d'un homme qui s'enfonce et de six autres qui le sortent sans toi. Dans le rêve, tu es toujours derrière les racines. Tu te réveilles avant de savoir si tu vas en sortir." },
      { if: { has: "xw:tombe_maraude" }, text: "Dans la mangrove du sud, une croix calée de pierres tient debout au pied d'un vieux palétuvier. *IL ÉTAIT BON.* Les crabes passent autour." },
      { if: { has: "xw:canot" }, text: "Sur la plage des crabes, sous un canot retourné, un pistolet rouillé et une balle qui n'a jamais servi attendent toujours quelqu'un qui ne viendra plus." },
      { if: { has: "fargue:tombe_annette" }, text: "Au bas du cimetière des Hollandes, contre le mur des pauvres, une dalle de granit gris, sans ange et sans dates : *ANNETTE FARGUE. ELLE CHANTAIT.* Les escargots passent dessus pour aller lire les noms du mur." },
      { if: { has: "fargue:fosse" }, text: "Sur le mur de la fosse des pauvres, au cimetière des Hollandes, un *A* et un *L* entrelacés s'effacent un peu plus chaque hiver sous la mousse. Personne d'autre ne sait qui ils étaient." },
      { if: { has: "ya:repris" }, text: "Dans la cour du nord du fort de Brisegrève, un forçat de quarante ans, numéro deux cent douze, regarde le ciel tous les soirs, couché sur le dos sur les dalles. Il apprend les étoiles aux nouveaux. Il leur montre le Clou du Nord, le seul qu'on peut croire." },
      { if: { has: "ya:rendu" }, text: "Jean-Marie Kerhervé, qui s'est rendu de lui-même sur le pont d'un trois-mâts, sort du fort de Brisegrève un matin de printemps, six mois avant son temps. Le vieux surveillant Tréhorel l'attend au bas de l'escalier, et lui donne un bonnet, et ne dit rien." },
      { if: { has: "ya:raye" }, text: "Le registre de l'Amirauté de Morlenc porte, à la page d'un jour de retour, la mort d'un gabier nommé Guérec, et, à la ligne suivante, l'embauche d'un gabier nommé Toussaint Davrigny, qui a choisi son nom tout seul en marchant dans une cour, et qui a pris celui de la médecin qui avait signé sa mort. Elle a trouvé ça très drôle, puis elle a dû s'asseoir." },
      { if: { has: "ya:fers" }, text: "L'Amirauté de Morlenc a reçu un forçat évadé, un livre de bord, et une capitaine qui a parlé pendant deux heures sans s'asseoir. Il a été gracié au bout de six semaines. On ne sait pas si c'est à cause du livre ou de la capitaine. L'Amirauté non plus." },
      { if: { has: "ya:reste" }, text: "Sur Folle-Aiguille, un géant vit seul dans une case au bord de la source, et se lève chaque matin sans regarder si on le regarde. Les Doux l'appellent par un nom de fleur. Il ne sait pas lequel. Il répond à tous." },
      { if: { has: "yb:envole" }, text: "Les marins du Couchant racontent qu'un albatros à l'aile marquée d'une cicatrice suit parfois les navires qui vont vers les îles, trois jours, pas un de plus. Ceux qui le voient lui jettent du biscuit. Personne n'a plus jamais tiré dessus." },
      { if: { has: "yb:capitaine" }, text: "On dit dans les tavernes de Morlenc que la capitaine Ribaud a privé la mer d'un homme, une nuit de calme, avec deux pistolets et une chemise de nuit. On ajoute que la mer s'en souvient. La capitaine répond que la mer a une mémoire de poisson rouge, et qu'elle lui doit encore deux bonnets." },
      { if: { has: "yb:rendu" }, text: "Barthélemy Coquerel, qu'on appelait Coq, a recommencé à rire, longtemps après, dans un port du Couchant. Il ne mange plus de volaille. Il donne une piastre à chaque enfant qui vend des oiseaux en cage sur les quais, et ouvre la cage." },
      { if: { has: "yb:jete" }, text: "Barthélemy Coquerel dort les yeux ouverts. Il dit qu'il a passé une nuit accroché aux chaînes d'un gouvernail, avec un oiseau mort pour compagnie, et que depuis, quand il ferme les yeux, il sent des choses molles lui frôler les jambes." },
      { if: { has: "yc:billet_rendu" }, text: "Au Cercle des Négociants de Morlenc, on raconte encore, à voix basse, l'histoire d'une veuve en gris qui a gagné un trois-mâts au pharaon, une nuit, contre Monsieur, et l'a rendu à son propriétaire sans rien demander. Monsieur ne la raconte jamais. On dit qu'il garde, dans son portefeuille, une carte qu'il ne joue plus." },
      { if: { has: "yc:perdu" }, text: "Victorine Davrigny ne touche plus jamais une carte, pas même pour une patience, pas même pour faire plaisir à l'abbé Morisseau, qui adore la bouillotte. Elle dit qu'elle a perdu cent livres un soir, à Morlenc, et compris pour cent livres une chose qui valait davantage." },
      { if: { has: "yc:mepris" }, text: "Le chevreau blanc né à bord de la Cormorane, un matin de tempête, s'appelle Baron. Il est devenu un bouc considérable, têtu, qui mange tout ce qu'on lui laisse et regarde ses sabots d'un air pensif." },
      { if: { has: "yd:mutins" }, text: "Le livre de bord de la Cormorane dit qu'un matelot nommé Tarlet a été attaqué de nuit, sur Folle-Aiguille, par des hommes de la plage. Les hommes de la plage ont toujours juré n'y être pour rien. On ne les a pas crus. Ils avaient tant fait d'autres choses." },
      { if: { has: "yd:chute" }, text: "Le livre de bord de la Cormorane dit qu'un matelot nommé Tarlet est tombé d'un oranger. Il a épousé sa fille de Kerverzot, avec une autre bague, en or celle-là, et très étroite. Il ne s'approche jamais des orangers." },
      { if: { has: "yd:inexplique" }, text: "Le livre de bord de la Cormorane contient une phrase que l'Amirauté de Morlenc a fait recopier pour ses archives, à titre de curiosité : *Le médecin du bord déclare ne pas savoir.*" },
      { if: { has: "yd:fondue" }, text: "Quelques balles vertes, de bronze, sont restées fichées dans les arbres autour de la Miséricorde. Les oiseaux n'y nichent pas." },
      { if: { has: "yd:enterree" }, text: "Au fond du verger de la Miséricorde, sous quatre pieds de terre rouge, une dame de bronze est couchée face contre terre, avec une bague d'argent au doigt. Les orangers, au-dessus, donnent des fruits très amers." },
      { if: { has: "yd:debout" }, text: "Une dame de bronze verte, aux yeux d'argent, se dresse toujours au fond du verger de la Miséricorde, contre un oranger mort. Elle regarde la mer, un peu au-dessus de l'horizon, avec une ironie que les années n'ont pas usée." },
      { if: { has: "ye:soeurs" }, text: "À la porte bleue de la rue des Tanneurs, une fille au fichu rouge lave les escaliers en chantant des chansons qu'on ne chante pas chez les Sœurs. Elle sait lire. Elle s'est sauvée trois fois. Elle est revenue trois fois, le soir même, à l'heure de la soupe." },
      { if: { has: "ye:denonce" }, text: "La veuve Gâche tient toujours école au bord du marais de Morlenc, dans une saline ou dans une autre. On dit qu'elle demande à chaque nouveau s'il connaît un mousse de la Cormorane, et qu'elle sourit, très doucement, quand on lui répond non." },
      { if: { has: "ye:vole" }, text: "Il te reste, de la saline du marais, une main qui pense à autre chose. Tu ne t'en sers jamais. Tu sais toujours, en revanche, dans une foule, où sont les montres, et où sont les mains qui les regardent." },
      { if: { has: "ye:pris" }, text: "Maître Gobert ne t'a jamais reparlé de la montre du Quai des Hollandes. Il ne t'a jamais appris une deuxième fois qu'on ne vole pas. C'était inutile." },
      { if: { has: "ye:refuse" }, text: "Il t'arrive de penser à une soupe de poisson, très bonne, servie dans des écuelles volées à trois tavernes, et à la seule maison de Morlenc où un enfant avait toujours à manger." },
      { if: { has: "ye:laisse" }, text: "Une fille au fichu rouge fait le Quai des Hollandes, les matins de Bourse. Elle a onze ans, puis douze. Ensuite, on ne la voit plus sur le quai." },
      { if: { has: "yf:fers" }, text: "Le juge de l'Amirauté de Lannoz a condamné le second Kerbiriou à cinq ans de galères pour deux pailles cassées. Les anciens du port disent que c'est la première fois qu'on juge la mer à terre. Matthieu a témoigné. Il a dit aussi, comme on le lui avait demandé, qu'il avait été ramené." },
      { if: { has: "yf:coutume" }, text: "Matthieu, novice de la Bonne-Espérance, est devenu un bon matelot. Il ne mange jamais de viande, et il ne tire jamais à la courte paille, même pour savoir qui ira chercher le vin." },
      { if: { has: "yf:tu" }, text: "Le second Kerbiriou commande une goélette, quelque part entre Lannoz et les îles. On dit qu'il est dur, juste, et qu'il ramène toujours ses hommes. On dit aussi qu'il tient lui-même les pailles, quand il y en a à tenir." },
      { if: { has: "yg:orange" }, text: "Anselme Prigent copie le livre de bord de la Cormorane jusqu'au retour, et descend à Morlenc avec une épluchure d'orange durcie dans sa poche. On ne sait pas ce qu'il est devenu. On sait qu'il a payé, de sa solde, une caisse d'oranges livrée au Fanal de la Pointe-aux-Corneilles, sans un mot." },
      { if: { has: "yg:lettre" }, text: "Un ancien commis de l'Amirauté a rouvert, à Morlenc, une petite boutique d'écrivain public sur le Quai des Hollandes. Il écrit les lettres des veuves de marins, gratuitement, et il les porte lui-même à la poste. Sur le mur, derrière lui, une lettre encadrée, cachetée, qu'il n'a jamais ouverte." },
      { if: { has: "yg:terre" }, text: "Il y a, à l'hospice du fort de Brisegrève, un homme pâle à lunettes rondes qui reste assis tout le jour devant une fenêtre, une écritoire fermée sur les genoux. Les sœurs disent qu'il est très poli, et qu'il ne demande rien." },
      { if: { has: "yh:mer" }, text: "Un pêcheur des îles du Couchant a repêché un jour, dans ses filets, un portrait d'homme dans un cadre doré, gonflé d'eau, souriant. Il l'a accroché dans sa case. Ses enfants l'appellent le Noyé Content." },
      { if: { has: "yh:chapelle" }, text: "Au-dessus de l'autel vide de la Miséricorde, un portrait d'homme en redingote sourit à la nef ruinée. Les Doux y montent parfois, cueillent des fleurs, et les posent au pied du mur. Ils lui ont donné un nom de fleur, comme à eux. Ils ne savent plus pourquoi." },
      { if: { has: "yh:garde" }, text: "Dans le bureau de Varnèse, le portrait d'Hector Davrigny, moisi, fendu, est accroché à l'endroit, face à la pièce. Victorine ne le retourne plus. Elle dit qu'il a fait le voyage, et qu'il a gagné le droit de regarder." },
      { if: { has: "yi:consigne" }, text: "Aurélie Clavières est tombée, un soir d'hiver, pendant que la Cormorane était aux îles. On l'a crue morte. Une vieille servante qui ne savait pas lire a tenu la porte de la chambre trois jours, un chapelet dans une main et un tisonnier dans l'autre. Le troisième soir, Aurélie s'est relevée, et a demandé l'heure." },
      { if: { all: [{ seen: "YI_aile" }, { not: { has: "yi:consigne" } }] }, text: "Aurélie Clavières est morte, dit-on, un soir d'hiver, pendant que la Cormorane était aux îles. On l'a mise au caveau de famille le lendemain, sous la chapelle de l'hôtel. Les domestiques ne descendent plus à la cave. Ils disent qu'on y entend, certaines nuits, à travers le mur, un bruit très faible et très régulier, comme quelqu'un qui frapperait avec des ongles." },
      { if: { has: "yi:certificat" }, text: "Le Conseil de Morlenc a nommé le baron Clavières curateur des biens de sa sœur, sur le certificat d'un médecin de Varnèse. Les biens ont beaucoup travaillé. Il n'en reste presque rien." },
      { if: { has: "yi:refus" }, text: "Les biens d'Aurélie Clavières dorment toujours, chez Maître Brindejonc, dans une liasse que personne n'a pu faire travailler, faute d'un certificat." },
      { if: { has: "yj:recompense" }, text: "On raconte dans les tavernes du Couchant l'histoire d'un canonnier qui arrêta seul une caronade folle, dans un coup de vent, avec un hamac et un anspect. On ne raconte jamais qui avait mal amarré la caronade. Les histoires ont leurs pudeurs." },
      { if: { has: "yj:puni" }, text: "Il arrive à Maître Gobert, quand il a bu, de dire qu'on a mis aux fers, une fois, l'homme qui avait sauvé son navire, et qu'il ne sait toujours pas si c'était juste. Il ajoute que c'était nécessaire. Il ne dit pas si c'est la même chose." },
      { if: { has: "yj:les_deux" }, text: "La capitaine Ribaud, devant l'Amirauté, cite parfois l'exemple d'une caronade, d'une bouteille de rhum et de trois jours de fers, quand on lui demande ce qu'est la discipline. Personne ne comprend. Elle ne l'explique pas." },
      { if: { has: "yl:dit" }, text: "Sur un poteau de la hutte, sous la Table, neuf entailles courtes et serrées ne ressemblent à aucun jour. Au Haut-Verger, on se repose toujours le mardi." },
      { if: { has: "yl:garde" }, text: "Sous la Table, un vieux calendrier de bois continue de retarder de neuf jours, en toute bonne foi. Au Haut-Verger, on se repose le mardi, et l'on chante." },
      { if: { has: "ym:barre" }, text: "Le livre de bord de la Cormorane porte, à la date d'une nuit de calme dans les Sargues, une ligne que les armateurs de Morlenc ont sautée : *l'officier de quart blessé, le mousse a manœuvré*." },
      { if: { has: "yn:argent" }, text: "Un maître d'équipage sans passé commande la manœuvre d'un caboteur de Lannoz. Il paie ses tournées avec des pièces qu'il sort d'un mouchoir brodé d'un G, et ne dit jamais d'où il vient." },
      { if: { has: "yn:proces" }, text: "Le tribunal de Morlenc a rendu la vie à Yves Jaouen, maître d'équipage, au bout de trois ans d'audiences, avec la moitié d'une boutique de la rue des Cordiers. Il ne l'a jamais ouverte. Il habite au-dessus, seul, et regarde la rue." },
      { if: { has: "yn:parti" }, text: "Rue des Cordiers, à la Basse-Fosse, une borne d'amarrage porte une marque taillée au couteau : un 7, et une croix. Les enfants du quartier croient que c'est un trésor de pirates. Ils ne sont pas loin." },
      { if: { has: "yo:place" }, text: "Rosemonde Lhuillier tient une batterie de côte à la pointe de Morlenc. Le soir, au feu des canonniers, elle s'assied toujours à la meilleure place, et personne ne songe à la lui disputer." },
      { if: { all: [{ has: "yo:defendue" }, { not: { has: "xs:baron_mort" } }] }, text: "Le baron Clavières n'a jamais pu entendre prononcer le mot « quinquina » sans changer de couleur. Rosemonde Lhuillier, elle, le prononce souvent, et lentement." },
      { if: { has: "yo:silence" }, text: "Rosemonde Lhuillier a quitté la mer. On dit qu'elle tient une ferme du côté de Varnèse, seule, et qu'elle ne parle à personne de la Miséricorde. On ne lui demande rien. Victorine Davrigny passe devant sa barrière, en tournée, et ne s'arrête pas. Elle ralentit, seulement." },
      { if: { has: "yp:tu" }, text: "Sous Sainte-Anne-des-Grèves, les noyés des Moines ont toujours leurs cierges, et les veuves de la Pointe leur pain d'hiver. La veuve Kerdudo est morte en balayant la nef, un samedi. On l'a mise au caveau, avec eux. On a dû déplacer quatre barils." },
      { if: { has: "yp:part" }, text: "Sur la lande de la Pointe, les nuits sans lune, on voit parfois passer une file d'ombres courbées sous des barils. La dernière marche toujours un peu à l'écart, comme quelqu'un qui pense à autre chose." },
      { if: { has: "yp:fouques" }, text: "Le brigadier Fouques a pris sa retraite sans avoir jamais descendu les six marches du caveau des Moines. À la Pointe, on le salue. Toi, quand tu reviens, on te sert, poliment, et on ne te parle plus de rien." },
      { if: { has: "fargue:loi" }, text: "Ewen Riou, gabier, a une cicatrice ronde au milieu de la main droite, des deux côtés. Il grimpe toujours aux vergues comme on monte un escalier. Il ne bégaie plus : il ne se met plus en colère." },
      { if: { has: "fargue:fouet" }, text: "Ewen Riou, gabier, porte sur le dos douze marques blanches, bien droites, bien serrées, données par un homme qui savait frapper. Il dit, quand on lui demande, que ce sont les plus justes qu'il ait reçues." },
      { if: { has: "fargue:mensonge" }, text: "Ewen Riou, gabier, n'a jamais remercié l'homme qui lui a sauvé la main sur une plage, au bout du monde, avec un mensonge. Il le regrette, certains soirs. Il ne sait pas à qui le dire." },
      { if: { has: "yr:averti" }, text: "Sur le Quai des Hollandes, les portefaix chantent toujours la chanson des sacs. Ils y ont ajouté un couplet, sur une nuit où trente hommes à trois livres sont repartis par les magasins. On ne sait pas qui l'a écrit. Thérèse Le Corre le chante plus fort que les autres." },
      { if: { all: [{ seen: "YR_quai" }, { not: { has: "yr:averti" } }] }, text: "Sur le Quai des Hollandes, la Chambre du Quai a repris un second sou par sac, l'année suivante, puis un troisième. Les portefaix ne chantent plus. On charge plus lentement. La Chambre s'en plaint." },
      { if: { has: "ys:brulee" }, text: "Monsieur de Pérignac vote désormais au Conseil de Morlenc selon sa conscience, ce qui rend ses votes parfaitement imprévisibles. Monsieur de Saint-Brice a perdu le premier vote de sa vie. Il a envoyé à Varnèse une caisse de vin de la Côte, avec ses compliments, et l'ordonnance qu'il n'a pas suivie." },
      { if: { has: "ys:rendue" }, text: "La raffinerie de Pérignac a fermé, l'hiver suivant. Madame de Pérignac a vendu une petite pierre très claire, et ouvert une confiserie sous les arcades de la Haute-Ville. On dit que c'est la meilleure de Morlenc. Elle n'a plus de vapeurs." },
      { if: { has: "ys:gardee" }, text: "Au fond d'une malle, dans une maison de Varnèse, sous deux robes grises, une lettre à l'encre violette attend qu'on se décide. Victorine Davrigny ne l'a jamais rendue. Elle ne s'en est jamais servie non plus. Elle la relit quelquefois, pour se rappeler qu'elle aurait pu." },
      { if: { has: "fargue:jacquemin_mensonge" }, text: "Au cimetière des Hollandes, contre le mur des pauvres, le nom de Jacquemin, cordier, est gravé au couteau sous celui d'une Annette. Deux dames de la Haute-Ville ont fait dire une messe pour leur père, un mois après. Elles ont dit à tout le monde qu'il était mort en les attendant. C'est vrai." },
      { if: { has: "fargue:jacquemin_verite" }, text: "Les cordiers de la porte des Saulniers chantent, en tordant le chanvre, une chanson qu'un maître-coq a chantée une nuit à un mourant. Ils ne savent pas d'où elle leur revient. Elle leur revient." },
      { if: { has: "fargue:jacquemin_fille" }, text: "La comtesse de Saint-Rémy ne va plus au bal de la Bourse. On dit qu'elle s'y est trouvée mal, une nuit, au milieu du menuet, et qu'elle a crié qu'on ôte de ses mains une odeur de chanvre qu'elle était seule à sentir." },
      { if: { has: "yv:accident" }, text: "Au cimetière de Lannoz, à côté de l'église, une croix de granit trop chère porte le nom de Guillemette Kervella. Le receveur la fleurit chaque dimanche. Il a payé les dettes de sa femme en vendant le jardin. Il dit qu'elle aimait les belles choses, et que c'est bien naturel." },
      { if: { has: "yv:verite" }, text: "Sur la lande de Lannoz, de l'autre côté du mur du cimetière, une pierre sans nom porte, chaque dimanche, un bouquet de bruyère. Le receveur des droits ne va plus à la messe. Il lit, le soir. Des romans à couverture jaune. Il ne les comprend pas. Il continue." },
      { if: { has: "yv:mari" }, text: "Le receveur des droits de Lannoz a vendu sa maison blanche et pris pension chez le recteur. Il soigne les ruches. Il dit à qui veut l'entendre que sa femme est morte d'une méprise, et il le dit avec une telle fermeté qu'on finit par comprendre qu'il a choisi d'y croire, et qu'on le laisse faire." },
      { if: { has: "yw:sable" }, text: "Au pied de la croix de Sainte-Anne-des-Grèves, à la Pointe-aux-Corneilles, il y a un peu de sable blanc mêlé d'éclats de coquillages roses, qu'aucune marée du Ponant n'a jamais apporté. Le vent l'emporte, grain par grain. Il y en a encore." },
      { if: { has: "yw:graine" }, text: "Derrière le Fanal, dans le jardin où rien ne pousse que les choux et le vent, un petit arbre maigre a levé, sur sept pépins, contre le mur de granit, à l'abri du nord. Il n'a jamais donné une orange. Lazare Hersant l'arrose tous les soirs." },
      { if: { has: "yw:promesse" }, text: "Sur une étagère, chez toi, un oiseau de bois rouge, très mal taillé, ouvre les ailes. Tu as promis. Les années passent, et la promesse ne s'use pas ; elle attend, comme lui, sur son étagère." },
      { if: { has: "yw:verite" }, text: "Sur une étagère, chez toi, un oiseau de bois rouge, très mal taillé, ouvre les ailes. Il ne sait pas ce que tu as dit à celui qui l'a fait. C'est peut-être pour ça qu'il a l'air content." },
      { if: { has: "yw:lettres" }, text: "Sept lettres écrites sur un tonneau, sur une plage du bout du monde, sont arrivées à Morlenc et à Lannoz. L'une d'elles disait qu'un homme avait quelque chose à dire, ou ne le disait pas. On ne sait pas laquelle. On ne saura pas." },
      { if: { has: "fargue:partie_arretee" }, text: "Nathanaël Brousse n'a jamais rejoué aux échecs. Il dit qu'il a gagné la seule partie qui comptait, contre un homme qui a couché son roi pour l'empêcher de devenir fou. Il ne dit pas le nom de l'homme." },
      { if: { has: "fargue:partie_gagnee" }, text: "Nathanaël Brousse a, dit-on, des absences. On le trouve assis devant un mur, à remuer les lèvres, à déplacer du bout du doigt des pièces que personne ne voit. Il gagne toujours." },
      { if: { has: "fargue:partie_perdue" }, text: "Nathanaël Brousse porte, au bout d'une ficelle, autour du cou, un petit roi d'ébène à la croix ébréchée. Il le serre dans sa main quand le temps tourne à l'orage. Il dit que c'est un porte-bonheur. Il ne dit pas qui le lui a donné." },
      { if: { has: "yy:dort" }, text: "Sur le glacis de Brisegrève, les soldats de la garnison racontent l'histoire d'un déserteur roux qui est mort en souriant aux mouettes, poliment, comme un invité. Ils disent que c'était un saint. L'aumônier ne les détrompe pas." },
      { if: { has: "yy:veille" }, text: "Victorine Davrigny ne s'est jamais habituée à rien. Elle dit, quand on le lui reproche, qu'elle a promis un jour à un garçon de vingt-deux ans de ne pas détourner les yeux, et qu'elle s'y tient, en général." },
      { if: { has: "yy:ecrit" }, text: "Quatorze feuillets d'une écriture serrée, intitulés *La nuit d'Aubin Kerrien, soldat*, circulent sous le manteau à Morlenc, recopiés de main en main. Le Conseil de guerre a demandé qu'on en trouve l'auteur. On ne l'a pas trouvé. On a cessé, depuis, de fusiller les déserteurs de Brisegrève à l'aube ; on les envoie aux galères, ce qui est un progrès." },
      { if: { has: "yz:avoue" }, text: "Marjolaine Cotentin garde dans sa chemise, contre sa peau, un paquet de lettres attachées par un fil de voile. Elle ne les relit plus. Elle sait qui les a écrites, et elle te salue, quand elle te croise sur un quai, d'un signe très bref, comme on se salue d'une hune à l'autre." },
      { if: { has: "yz:nie" }, text: "Marjolaine Cotentin croit, ou fait semblant de croire, qu'un gabier vaniteux lui a écrit, une traversée durant, les plus belles lettres du Couchant. Tu ne l'as jamais détrompée. Tu as écrit beaucoup d'autres lettres depuis. Aucune n'était aussi bonne." },
      { if: { has: "yz:laisse" }, text: "Dans ton coffre de marin, un paquet de lettres attachées par un fil de voile, que personne n'a jamais relues, attend que quelqu'un les jette à la mer. Elles étaient très bonnes. Elles n'ont servi à rien. C'est le sort de beaucoup de bonnes lettres." },
      { if: { all: [{ has: "za:remonte" }, { not: { has: "gaudremont:reste" } }] }, text: "Le professeur Gaudrémont raconte à l'Académie, chaque fois qu'on lui en laisse l'occasion, qu'il a eu le centre du globe à portée de corde, et qu'un mousse le lui a volé. Il le raconte avec une telle fierté qu'on ne sait jamais s'il se plaint du mousse ou s'il s'en vante." },
      { if: { all: [{ has: "za:seul" }, { not: { has: "gaudremont:reste" } }] }, text: "Dans une vitrine du cabinet d'histoire naturelle de Morlenc, une pierre rouge veinée de vert porte une étiquette de la main du professeur Gaudrémont : *Remontée du second puits de l'Écueil-Rouge, à une profondeur inconnue. Le feu continue.*" },
      { if: { all: [{ has: "za:verre" }, { not: { has: "gaudremont:reste" } }] }, text: "Sur la table de nuit du professeur Gaudrémont, il y a une aiguille de verre noir avec une bulle d'air dedans, qu'il ne montre à personne. Sa gouvernante dit qu'il lui parle, le soir. Elle exagère sans doute. Un peu." },
      { if: { has: "zb:ruban" }, text: "Dans le tiroir de ta table, il y a un ruban de soie, gris à force d'avoir été bleu, qui se défait un peu plus chaque année. Tu ne l'as jamais montré à aucun cavalier. Tu n'as jamais croisé de cheval pie." },
      { if: { has: "zb:danse" }, text: "Les soirs de brume, à la Pointe, il t'arrive d'entendre un violon, très loin, sur la lande. Ta main droite a froid. Tu n'y vas pas. Tu as promis à Zélie. Tu le regrettes, quelquefois, jusqu'au matin." },
      { if: { all: [{ has: "zc:pilules" }, { not: { has: "xs:baron_mort" } }, { not: { has: "fin:livre" } }] }, text: "Le baron Clavières ne voyage plus sans une boîte de pilules de Varnèse, souveraines contre tout, dont il distribue la recette à ses amis comme un secret d'État. Elle tient en trois mots. Il ne les connaît pas." },
      { if: { has: "zc:honoraires" }, text: "Dans le carnet de Victorine Davrigny, il y a une colonne de petites sommes, à cinq livres la visite, signées d'un baron, en déduction d'une dette. Elle ne l'a jamais montrée à personne. Elle la relit quand elle a besoin de rire, ou de rougir ; souvent les deux." },
      { if: { has: "zc:verite" }, text: "Un *Dictionnaire portatif de médecine, à l'usage des familles et des voyageurs*, en deux volumes reliés veau, est rangé dans la bibliothèque de Victorine Davrigny, entre un traité des fièvres et une Bible. Page quatre cent douze, une main a écrit dans la marge, d'une écriture de banquier : *peur*." },
      { if: { has: "zd:enterre" }, text: "Au pied du mur de la Miséricorde, sur l'éperon, il y a un long tas de pierres couché dans les cailloux, comme un cairn. Les Doux, qui ne savent pas ce que c'est, y posent des fleurs, par habitude, en passant. Victorine Davrigny a fait ses trois jours d'arrêts. Elle les recommencerait." },
      { if: { has: "zd:treve" }, text: "Sur la plage de l'Anse-Morte, une croix de bois flotté, plantée par des mutins, porte un nom écrit au couteau, Le Gall ou Le Garrec, on ne sait plus. On sait seulement qu'un jour, un drapeau blanc a été hissé pour lui, et qu'on l'a respecté des deux côtés." },
      { if: { has: "zd:chaux" }, text: "Au pied du mur de la Miséricorde, il y a une forme blanche dans les cailloux, que les pluies ont lavée et que les années ont aplatie, et qu'on prend de loin pour un rocher. À côté, une échelle de cordes pourrie. Victorine Davrigny en rêve, quelquefois. Elle se réveille avec un goût de chaux dans la bouche." },
      { if: { has: "ze:dit" }, text: "Sur la lande de Lannoz, dans une ferme du haut, un homme gris dort chaque nuit dans un lit clos, la petite fenêtre ouverte, quelque temps qu'il fasse. La servante dit qu'il dort mieux, depuis qu'un mousse de passage a eu la main prise. Elle dit aussi qu'il attend toujours." },
      { if: { has: "ze:tu" }, text: "Sur le dos de ta main droite, quand il fait très froid, quatre marques fines reparaissent, comme des doigts, et bleuissent. Tu n'en as jamais parlé. Les médecins disent que c'est la circulation." },
      { if: { has: "zf:denonce" }, text: "La chapelle de dissection de la Faculté de Morlenc est restée fermée deux ans. On l'a rouverte avec un règlement : chaque corps porte un nom, un registre, un certificat. Les étudiants l'appellent le règlement Jacotte, sans savoir pourquoi. Le professeur gras l'appelle autrement." },
      { if: { has: "zf:rachat" }, text: "Au cimetière des Hollandes, au pied du mur des pauvres, une tombe à part, sans nom, reçoit chaque printemps une botte de cresson. Personne ne sait qui l'apporte. Les fossoyeurs disent que c'est une dame de Varnèse, qui ne reste jamais longtemps." },
      { if: { has: "zf:disseque" }, text: "Victorine Davrigny a publié, sous un nom d'homme, un petit traité du trajet des nerfs de la cuisse, avec des planches d'une exactitude que la Faculté de Morlenc a saluée. Elle ne relit jamais la page de dédicace. Elle est vide. Elle l'a voulue vide." },
      { if: { has: "zg:drole" }, text: "Dans les tavernes du Couchant, on raconte une histoire d'abbé gourmand et de chapon d'évêque, qu'un matelot jure tenir d'une médecin, une nuit de siège, au bout du monde. On l'a beaucoup arrangée. L'abbé Morisseau l'a entendue à Varnèse, l'an dernier. Il a ri plus fort que tout le monde, et il a rougi." },
      { if: { has: "zg:vrai" }, text: "La capitaine Ribaud et Victorine Davrigny dînent ensemble, une fois l'an, à Morlenc, dans une auberge du port, devant une vraie bouteille. Elles parlent de Ferdinand et d'Hector. Elles rient beaucoup. Les garçons de salle les croient sœurs." },
      { if: { has: "zg:feu" }, text: "Victorine Davrigny doit toujours une histoire à la capitaine Ribaud. Elle ne la lui a jamais racontée. Elles se voient, de temps en temps, et la capitaine la lui réclame, et Victorine répond qu'elle n'a pas fini de la vivre." },
      { if: { has: "zh:surprise" }, text: "Sur la Cormorane, quand quelqu'un dit d'un autre qu'il est bête comme un panier, tout l'équipage éclate de rire, et les nouveaux ne comprennent pas. Gobert, lui, ne rit jamais. Il dit que c'était un éloge funèbre, et qu'on ne plaisante pas avec les éloges funèbres." },
      { if: { has: "zh:ecoute" }, text: "Tu connais par cœur une chanson de la côte, lente, sur un marin qui dort au fond de l'eau. Tu ne l'as jamais chantée. Tu l'as entendue une seule fois, accroché{joueur:e} à la chaîne d'un gouvernail, chantée pour toi." },
      { if: { has: "zi:dit" }, text: "Un quartier-maître breton, nommé Talec, a fini maître d'équipage sur un trois-mâts de Morlenc. On dit qu'il ne descend jamais à terre, et qu'il ne laisse jamais personne d'autre que lui fermer la marche, quand on quitte un navire." },
      { if: { has: "zi:tait" }, text: "Un quartier-maître breton, nommé Talec, tient toujours le canot, à l'arrière, l'aviron en travers des genoux. Il a une cicatrice à l'arcade, et un petit tremblement dans les mains, qui le quitte à l'instant précis où quelqu'un, à terre, a besoin de lui." },
      { if: { has: "zi:rame" }, text: "Sur la Cormorane, quand on cherche quelqu'un pour attendre au pied d'un volcan, d'une falaise ou d'une batterie ennemie, on n'a pas besoin de chercher. Talec est déjà dans le canot. Il dit qu'il a trouvé quelque chose, un jour, entre deux battements de cœur, et qu'il le garde." },
      { if: { has: "zj:revele" }, text: "Maître Aurélien Penven, notaire rue des Juges, a épousé la fille de l'armateur Le Meur. Il a dans son étude, au-dessus de son bureau, une petite gravure du bassin du Commerce à marée haute, que ses clients trouvent d'un goût douteux. Il ne s'en explique jamais." },
      { if: { has: "zj:client" }, text: "Maître Aurélien Penven, notaire rue des Juges, écrit encore chaque Noël à une dame de la Haute-Ville qu'il n'a jamais vue. Dans un de ses registres dort un testament plein de fautes d'orthographe, signé d'un cuisinier, qu'il a lu une fois sans rien comprendre." },
      { if: { has: "zj:loin" }, text: "Chez les sœurs de la Basse-Fosse, la sœur tourière garde, dans une boîte à ouvrage, des lettres adressées à une dame pieuse de la Haute-Ville, qu'aucune dame n'est jamais venue chercher. Elle les relit, quelquefois, le soir. Elle les trouve très bien tournées." },
      { if: { has: "zk:verite" }, text: "Monsieur Ollivier, marchand de grains à Varnèse, est mort au début de l'été, après avoir vendu lui-même les blés de Lannoz, à un prix dont on parle encore. Sa veuve n'a jamais pardonné à la médecin. Elle a gardé, pourtant, la dernière chose qu'il lui ait dite, et ne l'a répétée à personne." },
      { if: { has: "zk:menti" }, text: "Monsieur Ollivier, marchand de grains à Varnèse, est mort au début de l'été, d'un rein flottant, selon le docteur Hautecœur, en souriant à tout le monde jusqu'à la fin. Une tapisserie inachevée pend, depuis, dans le salon de la grande maison de la place." },
      { if: { has: "zk:question" }, text: "Monsieur Ollivier, marchand de grains à Varnèse, est mort au début de l'été, sa petite-fille sur les genoux, après avoir renvoyé son médecin et mangé, en trois mois, plus d'huîtres que tout le reste du bourg. Son gendre a payé la note. Elle était longue." },
      { if: { has: "zl:ruse" }, text: "Une perle noire, la plus petite d'une bourse de trente, dort au fond d'un tiroir, chez toi. Tu ne l'as jamais vendue. Tu la sors quelquefois, et tu la fais rouler dans ta paume, et tu entends un vieux rire de gorge, sans dents." },
      { if: { has: "zl:vrai" }, text: "Tu portes au cou, dans un petit sac de cuir, une perle noire grosse comme un pois chiche. On t'en a offert des fortunes. Tu réponds qu'elle n'est pas à vendre, qu'elle est à toi, et que tu aimes la regarder." },
      { if: { has: "zl:rien" }, text: "Tu retiens ton souffle deux minutes, sous l'eau. Tu ne sais plus très bien qui te l'a appris. Il te semble, quand tu remontes, qu'une voix finit de compter." },
      { if: { has: "zm:repas" }, text: "Sur la falaise ouest de Brisegrève, les douaniers ont pris l'habitude d'un vieil homme qui vient s'asseoir là chaque soir, pieds nus, ses souliers à côté de lui, et qui regarde la mer jusqu'à la nuit, toute la mer, de tous les côtés. Il vit de pêche à la ligne. On l'appelle par son nom." },
      { if: { has: "zm:barque" }, text: "Une œuvre de dames, à Morlenc, a reçu un jour un vieil homme qui tremblait, un baluchon serré contre la poitrine. Il y a vécu, dit-on, quatre ans. On l'a enterré avec une petite boîte dans laquelle il avait gardé une araignée morte, séchée, très ancienne." },
      { if: { has: "zm:porte" }, text: "Les lanternes du rempart de Brisegrève s'allument chaque soir du nord au sud, une à une. La dernière, au sommet de la tour du nord, s'allume toujours un peu plus tard que les autres. Les navires qui passent ont fini par s'en servir d'amer." },
      { if: { has: "zn:signe" }, text: "Monsieur de Kerangal a épousé en secondes noces une demoiselle de Varnèse. À l'asile de Morlenc, dans une salle basse, une femme aux cheveux noirs plie des bateaux de papier avec les pages d'un vieux missel. Les gardiennes disent qu'elle est douce. Elles la plaignent. Elle n'a plus de visites." },
      { if: { has: "zn:refuse" }, text: "Au manoir de Kerangal, on a remplacé le papier huilé des fenêtres par des vitres, et ouvert la lucarne du grenier. Personne, à Lannoz, ne sait au juste ce qui s'est passé. On voit seulement, certains jours, une femme aux cheveux noirs qui marche dans l'allée des hêtres, très lentement, au bras de son mari, qui ne lui parle pas." },
      { if: { has: "zn:recteur" }, text: "À la messe de Lannoz, le dimanche, Madame de Kerangal occupe le premier banc, à côté de son mari. Toute la paroisse la regarde. Elle a repris des couleurs. Elle a donné au recteur, pour ses ruches, une flottille de bateaux de papier, qu'il a mise dans la sacristie, et qu'on montre aux étrangers." },
      { if: { has: "zo:lettre" }, text: "À la Pointe-aux-Corneilles, la veuve Gourvès a quitté le deuil un printemps, sans rien expliquer à personne, et pris la diligence de Morlenc avec sa fille. Elles sont revenues trois semaines après. Elles étaient deux. Soizic a jeté dans la mer, du haut de la falaise, une vieille chique de tabac." },
      { if: { has: "zo:fille" }, text: "Un jour d'été, un bateau peint en bleu est entré dans l'anse de la Pointe-aux-Corneilles, mené par un homme maigre aux cheveux gris, qui avait un pouce coupé. Il est resté longtemps dans le bateau, sans descendre. C'est une fille de quinze ans qui est entrée dans l'eau jusqu'à la taille pour aller le chercher." },
      { if: { has: "zo:tait" }, text: "À la Pointe-aux-Corneilles, la veuve Gourvès a fini par épouser le meunier de Varnèse. Soizic garde toujours, dans une boîte à sel, une chique de tabac qui ne sent plus rien. Toi, chaque fois que tu passes devant une cave à l'enseigne d'un pélican, tu presses le pas." },
      { if: { has: "zp:joue" }, text: "Dans les tavernes de la Basse-Fosse, un gabier maigre à figure de fouine fait rire les buveurs en imitant tout le monde, les capitaines, les armateurs, les curés. On lui demande souvent de faire un maître-coq, un gros homme à la louche, dont on lui a parlé. Il refuse toujours. Il dit qu'il ne sait pas." },
      { if: { has: "zp:masque" }, text: "Les hommes qui étaient au camp de la plage, à Folle-Aiguille, gardent tous le souvenir d'un soir où le rire s'est arrêté autour du feu. Ils ne sont pas d'accord sur ce qu'ils ont vu. Ils sont d'accord sur le silence." },
      { if: { has: "zp:demande" }, text: "Yvon Mével, de la rue des Cordiers, est devenu comédien, à Morlenc, au théâtre des Quais. Il est célèbre pour un seul rôle : un traître jovial, dans un mélodrame de pirates, qui fait pleurer les dames au deuxième acte et trembler les enfants au troisième. Les critiques trouvent qu'il le joue avec une vérité inquiétante." },
      { if: { has: "zq:vrai" }, text: "Au Haut-Verger de Folle-Aiguille, un garçon des Doux a cessé, un jour, de mâcher l'écorce. On dit qu'il pleure souvent, et qu'il rit aussi, plus fort que les autres. On dit qu'il appelle les Doux par leurs noms, un par un, chaque matin, et qu'ils s'en étonnent." },
      { if: { has: "zq:beau" }, text: "Au Haut-Verger de Folle-Aiguille, un garçon des Doux descend quelquefois sur la plage, le dimanche, au lever du jour, et tend l'oreille vers le nord, la tête penchée, comme quelqu'un qui écoute sonner des cloches très lointaines." },
      { if: { has: "zq:garde" }, text: "Quelque part, sur une île du Couchant, un garçon qui a oublié ton nom porte à sa ceinture un galet noir à veine blanche. Il le touche chaque matin, et il sait qu'il y avait quelqu'un, le jour où le rocher chantait." },
      { if: { has: "zr:sacoche" }, text: "Sous la terre de Folle-Aiguille, dans les galeries des Puits, une femme aux bras brûlés soigne les enfants qui toussent, avec des gestes de forgeronne et des livres qu'elle ne sait pas lire, dont elle connaît les planches par cœur. Les fioles sont vides depuis longtemps. Elle a appris à faire le sirop elle-même, avec des pavots du Haut-Verger." },
      { if: { has: "zr:lumiere" }, text: "À Folle-Aiguille, certains matins, des enfants pâles sortent des Puits et viennent s'asseoir au soleil sur le parvis de la vieille chapelle, avec une femme aux yeux bandés, et ils restent là des heures, à regarder le ciel. Ils ne sont pas devenus des Doux. Ils toussent moins." },
      { if: { has: "zr:promesse" }, text: "Victorine Davrigny a écrit, depuis son retour, à quatorze armateurs, trois sociétés savantes, deux évêques et l'Amirauté, pour qu'on arme un navire vers une île du Couchant où onze enfants toussent noir. Elle a reçu deux réponses polies. Elle continue d'écrire." },
      { if: { all: [{ has: "zs:seme" }, { not: { has: "victime=freville" } }] }, text: "Abel Fréville, charpentier, n'a plus jamais signé pour un voyage dont on ne lui disait pas la destination. Il porte toujours son scapulaire, recousu de gros points serrés. Il dit qu'il a douté, une fois, sur la mer des Sargues, d'une personne qui ne le méritait pas, et qu'il ne sait plus pourquoi." },
      { if: { all: [{ has: "zs:rassure" }, { not: { has: "victime=freville" } }] }, text: "Abel Fréville, charpentier, explique à ses enfants, le soir, que les chapelles sur les cartes sont des phares de pierre, qui ne coûtent pas d'huile. Il le tient d'un cuisinier, dit-il, qui savait des choses." },
      { if: { has: "zs:arrete" }, text: "Dans une boîte de fer, sous un hamac qui n'est plus le sien, il y a une aiguille à repriser, avec un bout de fil brun, qu'on n'a jamais rangée dans la trousse. Celui qui l'a gardée savait pourquoi. Il ne l'a dit à personne." },
      { if: { has: "zt:montre" }, text: "Tu as une montre d'argent à couvercle gravé d'une ancre, qui sonne l'heure. Elle n'a jamais retardé d'une minute. Tu ne la portes pas. Elle dort dans un tiroir, et quelquefois, la nuit, tu crois l'entendre sonner, trois petits coups clairs, à travers le bois." },
      { if: { has: "zt:cache" }, text: "Au bourg de Lannoz, dans la troisième maison, celle du figuier, une veuve nommée Jaffré attend un fils qui est venu jusqu'à la lande, un jour, et qui a presque vu le clocher. On lui a dit qu'un enfant du navire l'avait caché. Elle prie pour cet enfant-là." },
      { if: { has: "zt:rien" }, text: "Un garçon nommé Jaffré a fait deux ans de plus sur le garde-côte de l'Amirauté, puis il est rentré à Lannoz, avec son congé. Il raconte, à la veillée, qu'un vieux sergent lui a sauvé la vie en regardant ailleurs, et qu'un enfant lui a sauvé la vie en ne regardant nulle part." },
      { if: { has: "zu:tirade" }, text: "Dans les foires du Ponant, la troupe Brisquet joue toujours *Le Matamore puni*. Au cinquième acte, quand le page lève son épée de bois, toute la salle récite les vers avec lui. On dit que la coutume vient de Morlenc, d'un soir où des gourdins sont montés sur la scène. Personne ne se souvient du nom du page." },
      { if: { has: "zu:combat" }, text: "Tu as une petite cicatrice à la lèvre, cousue au fil rouge par une comédienne. Dans un coffre, chez toi, il y a une épée de bois peinte en argent, cassée en deux. Tu n'as jamais pu te résoudre à la recoller." },
      { if: { has: "zu:coulisse" }, text: "Tu as appris, depuis, à porter des costumes plus lourds qu'un pourpoint de satin bleu. Quelquefois, au moment de les endosser, tu entends une grosse voix de basse te dire qu'il faut les porter longtemps." },
      { if: { has: "zv:piege" }, text: "Madame Desroches, veuve d'armateur, a vécu onze ans de plus, en mangeant beaucoup. Elle a repris l'*Espérance* à l'Œuvre des Âmes du Purgatoire par un procès retentissant. L'abbé Vauquelin dirige à présent les consciences d'une autre ville. Il y fait, dit-on, beaucoup de bien." },
      { if: { has: "zv:dit" }, text: "Madame Desroches, veuve d'armateur, est morte en odeur de sainteté, l'hiver qui a suivi, à Morlenc. L'abbé Vauquelin a prononcé son oraison funèbre. Il y a parlé d'une femme, venue de Varnèse, que le démon avait envoyée, et qu'elle avait su repousser." },
      { if: { has: "zv:laisse" }, text: "À Morlenc, dans la Haute-Ville, on vend l'eau de Lourmes au prix de l'eau-de-vie. Les dévotes en boivent trois fois par jour. Une jeune femme de la rue des Juges en achète un flacon chaque semaine, qu'elle vide dans l'évier en rentrant, et qu'elle remplit d'eau de source." },
      { if: { has: "zw:eau" }, text: "On raconte, dans les ports du Couchant, l'histoire d'un brick sans équipage qu'on aurait vu passer, un jour, au large d'une côte, avec à la barre un homme très grand qui ne la lâchait pas. On ne dit pas s'il a touché terre. Les marins qui la racontent préfèrent penser que oui." },
      { if: { has: "zw:barre" }, text: "Annick Lemerle, timonière, n'a jamais dit un mot de ses cinq jours sur le brick des Palmes. Elle porte, depuis, à son cou, une petite figure de bois noir, taillée au couteau, qu'elle touche avant chaque quart. Elle dit que c'est pour la chance. Elle dit qu'elle l'a gagnée." },
      { if: { has: "zw:loi" }, text: "Le registre de l'Amirauté de Lannoz porte, à la date du passage de la Cormorane, la mention d'une prise : un brick, et cent douze pièces, vendues au profit de l'Amirauté. En marge, une main de femme a écrit au crayon un nom, Madou, que le greffier n'a pas effacé." },
      { if: { has: "zx:refus" }, text: "À la corderie Ropars, au bout du hangar, un homme roux et voûté tourne la roue des torons. Il a trente ans. On dirait cinquante. Il a demandé, une fois, à monter sur un navire. On le lui a refusé. Il n'a jamais redemandé." },
      { if: { has: "zx:debarque" }, text: "Un enfant trouvé de Morlenc, ramené de Brisegrève par un navire de l'État, s'est enfui de la corderie Ropars le printemps suivant, et n'a jamais été repris. On dit qu'il s'est engagé sous un faux nom, sur un baleinier. On dit qu'il ne dénonce jamais personne." },
      { if: { has: "zx:reste" }, text: "Au rôle de la Cormorane, à la date du départ de Folle-Aiguille, il est écrit : *Erwan, novice, tombé de la falaise. Paix à son âme.* Sur l'île, un garçon roux pêche à la ligne au pied de la falaise, et il n'est à personne." },
      { if: { has: "zx:part" }, text: "Erwan, dit le Rouquin, enfant trouvé de Morlenc, est passé matelot au troisième voyage, et maître d'équipage au dixième. Il ne prend jamais d'enfant loué à bord. Il en prend souvent qui se sont cachés dans la soute." },
      { if: { all: [{ has: "zx:engage" }, { not: { has: "zx:reste" } }, { not: { has: "zx:part" } }] }, text: "Erwan, dit le Rouquin, novice de la Cormorane, a fini par être à quelqu'un : à lui-même, ce qui est le plus difficile. Il lui a fallu longtemps. Il dit qu'un mousse de la Pointe-aux-Corneilles lui a appris à commencer." },
      { if: { all: [{ has: "zy:rase" }, { not: { has: "xs:baron_mort" } }] }, text: "Le baron Clavières raconte, dans les salons de Morlenc, qu'il s'est fait raser sous le feu, sur le mur d'une chapelle assiégée, par une femme médecin dont la main n'a pas tremblé. On ne le croit pas. On le trouve vantard. C'est la seule de ses histoires qui soit vraie." },
      { if: { all: [{ has: "zy:refuse" }, { not: { has: "xs:baron_mort" } }] }, text: "Le baron Clavières porte, sur la joue gauche, trois petites cicatrices parallèles, qu'il refuse de faire soigner par les chirurgiens de Morlenc. Il dit que c'est un souvenir de barbier. Il garde, dans un tiroir, un éclat de miroir." },
      { if: { all: [{ has: "zy:descend" }, { not: { has: "xs:baron_mort" } }] }, text: "On a vu, à Morlenc, le baron Clavières saluer une seule fois Victorine Davrigny, dans la rue, d'un salut profond, ironique, interminable, comme on salue un adversaire qui a gagné une partie qu'on aurait dû perdre." },
      { if: { has: "zz:lit" }, text: "Bleunven, ramendeuse à la Pointe-aux-Corneilles, ne s'est jamais mariée. Elle raccommode les filets de tous les bateaux de la côte, plus vite que personne. Elle demande à chaque équipage qui rentre des bancs du Nord s'ils n'ont pas vu, dans le brouillard, un aviron peint en vert." },
      { if: { has: "zz:invente" }, text: "Bleunven, ramendeuse à la Pointe-aux-Corneilles, garde dans un coffret quatre lettres, dont une qu'aucun homme n'a dictée. C'est celle qu'elle relit. Elle la sait par cœur. Elle n'a jamais dit à personne qui l'avait écrite, ni si elle lui en voulait." },
      { if: { has: "zz:recteur" }, text: "Bleunven, ramendeuse à la Pointe-aux-Corneilles, a épousé, quatre ans plus tard, un pêcheur de Varnèse. Le jour de ses noces, en sortant de Sainte-Anne, elle a cherché quelqu'un des yeux, dans la foule, et lui a fait un petit signe de la main." },
      { if: { has: "wa:dehors" }, text: "Un gabier de Morlenc, rentré de Folle-Aiguille maigre comme un clou, salue poliment, dans la rue, une femme médecin de Varnèse, comme on salue quelqu'un qu'on a connu ailleurs. Il n'a jamais raconté à sa fiancée les douze nuits de la cabane." },
      { if: { has: "wa:dedans" }, text: "Victorine Davrigny tient, dans un carnet à part, le compte des morts de la sacristie de la Miséricorde, et de ceux de la nef. Elle refait l'addition, certains soirs, en changeant les hypothèses. Elle ne trouve jamais le même résultat." },
      { if: { has: "wa:avec" }, text: "Un gabier de Morlenc a épousé une fille nommée Mathurine, et il a un chien nommé Mathurin. Il a voulu appeler sa première fille Victorine. Sa femme a dit non. Il a insisté. Elle s'appelle Victorine." },
      { if: { has: "wb:defend" }, text: "Sur la lande de la Pointe-aux-Corneilles, une rebouteuse aux yeux verts remet les os des bêtes et des gens. On l'appelle Katell, à présent. On va la voir par le chemin de devant. Au pardon de Sainte-Anne, elle s'assied au dernier banc, et garde une place à côté d'elle." },
      { if: { has: "wb:secret" }, text: "Tu sais où nichent les pétrels, sur la falaise de la Pointe. Personne d'autre ne le sait, à part une rebouteuse de la lande que tu allais voir par le chemin de derrière. Tu n'y es jamais allé{e} par devant." },
      { if: { has: "wb:moque" }, text: "Ta cheville gauche ne t'a jamais fait souffrir, de toute ta vie, même dans les pires tempêtes. Quelquefois, l'hiver, il te semble entendre un grillon dans la cheminée. Tu le sais : ce n'est pas la saison." },
      { if: { has: "wc:coup" }, text: "À Lannoz, sur la lande, il y a deux croix de plus que l'année d'avant, à deux cents pas l'une de l'autre, et une jeune femme en coiffe noire qui les fleurit toutes les deux, le même jour, avec les mêmes bruyères. On ne sait pas pourquoi les deux. Elle le sait." },
      { if: { has: "wc:chute" }, text: "À Lannoz, un tourbier roux, doux, qui aime les moutons, a épousé une fille qui ne chante plus à la veillée. Les vieux ont cessé de cracher dans le feu quand il entre. Ils ont mis dix ans." },
      { if: { has: "wc:doute" }, text: "À Lannoz, on jure désormais sur les corps, devant le recteur, plutôt que de prendre le louchet. On appelle cela, dans la langue de l'île, d'un mot qui veut dire à peu près « la manière de l'étrangère »." },
      { if: { has: "wd:chaleur" }, text: "Maître Gobert, retiré à terre, raconte encore, devant le feu, qu'un mousse lui a sauvé la vie une nuit, sur une lande, en se couchant contre lui comme un chien. Il ne dit jamais ton nom. Il dit « mon morveux », et sa voix change." },
      { if: { has: "wd:part" }, text: "Tu as appris, une nuit, sur une lande, qu'on peut faire ce qu'il fallait faire et laisser quelqu'un seul dans le noir, en même temps, avec les mêmes jambes. Tu l'as réappris plusieurs fois, depuis. C'est chaque fois aussi difficile." },
      { if: { has: "wd:moutons" }, text: "Tu ne manges jamais de mouton. On te trouve des manies de vieux marin. Tu laisses dire." },
      { if: { has: "we:passe" }, text: "Il t'arrive, les soirs de pluie, de regarder sous les porches. Tu ne sais pas ce que tu cherches. Un homme aux yeux pâles, peut-être, ou le papier que la pluie avait collé aux pavés, avec un visage dessus." },
      { if: { has: "we:garde" }, text: "Un gabier aux yeux pâles, d'une écriture penchée, régulière, t'envoie une lettre chaque année, d'un port différent, sans signature. Elle dit toujours la même chose : *Toujours vivant. Merci.*" },
      { if: { has: "we:capitaine" }, text: "La capitaine Ribaud a gardé à son bord, jusqu'à sa retraite, un gabier aux yeux pâles qui chantait juste et dont le nom changeait sur chaque rôle d'équipage. Elle disait qu'un mousse le lui avait envoyé, un soir, en guise de cadeau." },
      { if: { has: "we:dit" }, text: "Personne ne sait si Ronan Guillerm a nagé deux milles, cette nuit-là, au large de Brisegrève. Tu as gardé son papier. Tu le relis parfois. Tu n'as jamais décidé si c'était un pardon." },
      { if: { has: "wf:or" }, text: "À la Grande-Lande, maître Rospabu est mort sans avoir reparlé à sa fille. Agathe a hérité de tout, à quarante ans. La première chose qu'elle a faite a été d'allumer un feu dans chaque cheminée de la maison, en plein été, et de les laisser brûler toute une nuit." },
      { if: { has: "wf:pere" }, text: "L'abbé Morisseau raconte volontiers comment il a fait plier, un soir, l'homme le plus riche de la lande, pour une demi-once d'écorce. Victorine, quand elle l'entend, ne le contredit pas. Elle compte, en silence, les trois années de toux." },
      { if: { has: "wf:offre" }, text: "Victorine Davrigny n'a jamais remboursé le premier créancier d'Hector. Agathe Rospabu, à la mort de son père, lui a fait porter un jour par un notaire une petite bourse de cuir, avec vingt-huit pièces, sans un mot. Victorine l'a rendue. Agathe l'a renvoyée. Cela dure encore." },
      { if: { has: "wg:avertit" }, text: "À la Tour-aux-Rats, à Morlenc, le gardien-chef Mauduit est mort dans son lit, très vieux, très riche, et très aimé de ses supérieurs. Le biscuit de mer y est meilleur que jamais. On y met du saindoux, pour les officiers." },
      { if: { has: "wg:soudoie" }, text: "Lucien Fargue n'a jamais su combien de temps avaient duré ses trente livres de paix, à la Tour-aux-Rats. Il ne l'a jamais demandé. C'est le seul argent dont il n'ait jamais voulu connaître le rendement." },
      { if: { has: "wg:tait" }, text: "À la Tour-aux-Rats, les forçats du fournil coupent encore leur pain en deux, le dimanche, et en donnent la moitié au plus maigre. Ils appellent cela « la part du géant ». Les gardiens ont renoncé à l'interdire." },
      { if: { has: "wh:plaide" }, text: "Au camp de la cascade, un homme très grand, sourd et muet, fait parfois, la nuit, un petit bruit aigu, joyeux, avec sa gorge. Les enfants du camp, qui ont appris à pleurer sans bruit, l'imitent en secret, et rient, sans bruit." },
      { if: { has: "wh:voix" }, text: "Victorine Davrigny n'a jamais refait l'opération des cordes. Elle en a décrit la technique, pourtant, dans son traité, en note, sans un mot de commentaire, entre la trachéotomie et l'ablation des amygdales." },
      { if: { has: "wi:harangue" }, text: "Ulric Malandain a gardé toute sa vie, contre Lucien Fargue, la rancune particulière d'un homme brave qu'on a laissé seul au milieu d'un cercle, en lui donnant raison. Il disait que le cuisinier parlait comme on vide un poisson : en remerciant la bête." },
      { if: { has: "wi:vrai" }, text: "Lucien Fargue a dit la vérité, une fois, à quarante hommes à la fois, sur une plage. Il racontait plus tard que ce fut le pire discours de sa vie, et le seul dont il n'ait pas eu honte." },
      { if: { has: "wi:louche" }, text: "Il y a, sur une plage de Folle-Aiguille, sous le sable, un gabier de dix-neuf ans qu'on a enterré l'estomac plein, en chantant sa chanson. On dit que c'est la meilleure manière. Ceux qui y étaient le disent." },
      { if: { has: "wj:verite" }, text: "À l'asile de Morlenc, une femme en robe grise, guérie, dit-on, travaille à la lingerie. Elle refuse les crêpes. Chaque année, à la même date, elle demande un jour de congé, et personne ne sait où elle va." },
      { if: { has: "wj:jeu" }, text: "Sur le roc de Brisegrève, un vieux sergent et une petite veuve attendent encore, chaque midi, devant la porte du fort, l'un debout et l'autre assise. La garnison change tous les trois ans. Chaque nouvelle sentinelle apprend la phrase." },
      { if: { has: "wj:aveu" }, text: "À Brisegrève, au bord du fossé côté mer, quelqu'un a planté une croix de bois, sans nom. Une femme et un vieux sergent la fleurissent ensemble, une fois l'an. Ils ne se parlent pas, ces jours-là. Les autres jours, ils jouent aux cartes." },
      { if: { has: "wk:medecin" }, text: "À la foire du Quai-aux-Harengs, une baraque de toile grise a disparu, l'année d'après, avec son maître et son Rieur. On dit que le gros homme a pris peur d'une femme médecin, et qu'il a revendu le garçon à un cirque, très loin. On dit aussi qu'il l'a laissé partir. On ne sait pas." },
      { if: { has: "wk:fuite" }, text: "Tu as appris, sous une toile grise, que la porte ouverte ne suffit pas, quand on porte sa prison sur sa figure. Tu en as reconnu d'autres, depuis, qui ne portaient rien de visible." },
      { if: { has: "wk:nom" }, text: "Quelque part, dans une foire, un homme au rire fendu jusqu'aux oreilles porte en secret le prénom de ta mère. Tu ne l'as jamais revu. Tu penses à lui, quelquefois, comme à un cousin." },
      { if: { has: "wl:eau" }, text: "La mère Le Hir a vécu jusqu'à quatre-vingt-sept ans, en buvant chaque soir son remède, qu'elle trouvait de plus en plus mauvais. Mathelin Quiniou est mort avant elle, d'une attaque, en comptant sur ses doigts. La ferme est allée à ses héritiers, qui ont dû continuer à payer la rente." },
      { if: { has: "wl:dit" }, text: "On dit à la Pointe que la mère Le Hir a eu le plus bel enterrement du pays, payé par l'homme qui l'avait tuée, et qu'elle l'avait prévu. Tu es la seule personne à savoir qu'on le dit à raison." },
      { if: { has: "wl:sert" }, text: "Tu ne sers jamais d'eau-de-vie à une vieille femme sans regarder qui paie. On trouve ça étrange. Tu ne l'expliques pas." },
      { if: { has: "wm:dit" }, text: "Un apothicaire du Quai des Hollandes a vu, un matin, entrer dans sa boutique une femme médecin en manteau de mer, avec un coffre de bois sec sous le bras. On ne sait pas ce qu'elle lui a dit. Il a vendu sa boutique dans le mois." },
      { if: { has: "wm:cache" }, text: "Victorine Davrigny a gardé un journal de bord médical, en latin, dont une page porte trois mots qu'elle n'a jamais barrés. Elle a appris, depuis, à goûter le fond de chaque coffre. Elle le fait devant le marchand, longuement, en le regardant." },
      { if: { has: "wn:temoigne" }, text: "On dit que les jeunes des Puits remontent à présent, chacun leur tour, pour un jour, puis pour deux, puis pour une saison. Les Mères laissent faire. Elles disent que l'enfant d'en haut a menti comme on dit la vérité, et que c'est pire." },
      { if: { has: "wn:silence" }, text: "Au fond des Puits, au soufflet de la forge, un homme pâle dit tout bas, en pompant, un mot qui ressemble à « mer ». Les enfants qui l'entendent croient que c'est une prière. C'en est peut-être une." },
      { if: { has: "wn:remonte" }, text: "Sur Folle-Aiguille, au bord d'un puits dans les fougères, un homme pâle a construit une cabane face à l'est. Il a appris à faire le feu, à trouver l'eau douce, à nommer les oiseaux. Il ne redescend jamais. Il attend, chaque matin, que le soleil se lève, comme si ce n'était pas sûr." },
      { if: { all: [{ has: "wm:baron" }, { not: { has: "xs:baron_mort" } }] }, text: "Le baron Clavières a raconté souvent, à la Bourse de Morlenc, comment une femme médecin lui avait arraché, en pleine mer, la moitié de son écorce. Il en riait. Il ne disait jamais qu'il avait dit oui." },
      { if: { has: "wo:paie" }, text: "Jules Arnoult, qu'on a appelé Petit-Jules jusqu'à quarante ans, n'a jamais rejoué aux dés. Il épluche les oignons plus vite que n'importe quel cuisinier de Morlenc, et il raconte, à qui veut l'entendre, qu'il les épluche pour payer une dette, et qu'il ne l'aura jamais finie." },
      { if: { has: "wo:lettre" }, text: "Un papier graisseux, écrit en lettres rondes par un homme ivre, avec une croix au bas, a passé le reste de sa vie dans la poche d'un vieux cuisinier. Il le relisait quelquefois, en riant tout seul, pour se rappeler que toutes les lois ont un trou." },
      { if: { has: "wo:des" }, text: "Hilaire Boucaut n'a plus jamais joué aux dés, sur aucun navire. Il a gardé, de cette nuit-là, un œil qui ne s'ouvre qu'à moitié, et la conviction que les cuisiniers sont les plus dangereux des hommes." },
      { if: { has: "wp:tonneau" }, text: "Tu as appris, dans un remous, au fond de la peur, à regarder ce qui flotte. Tu n'as jamais désappris. On dit de toi, dans les mauvais moments, que tu as un sang-froid de noyé." },
      { if: { has: "wp:barque" }, text: "Isidore Lagadec, le Hareng, est mort dans son lit, très vieux, en serrant la main de quelqu'un qu'il prenait pour un mousse. Il a dit, avant de mourir : « Le Remous fait du bruit. » Personne n'a compris." },
      { if: { has: "wp:lagadec" }, text: "Tu portes au bras gauche une marque de dents en demi-lune. On te demande souvent ce que c'est. Tu réponds que c'est un vieux marin qui ne voulait pas mourir, et que tu ne le lui as pas permis." },
      { if: { has: "wq:joue" }, text: "Tu racontes encore, quelquefois, les histoires de Hinault, toutes fausses, toutes admirables. Tu les racontes mieux que lui. Tu ne racontes jamais la dernière nuit." },
      { if: { has: "wq:medecin" }, text: "Victorine Davrigny a noté, dans son journal, la mort d'un gabier de la Basse-Fosse, « poitrinaire, et comédien jusqu'à ce qu'on l'en empêche ». Elle a ajouté en marge : « L'enfant a bien fait. Moi aussi. Lui non. »" },
      { if: { has: "wq:dit" }, text: "Quelque part à la Basse-Fosse, une vieille femme qui vendait des moules a reçu un jour la visite d'un{e} jeune marin qui lui a parlé de son fils, longtemps, avec des histoires très ordinaires, et qui a laissé de l'argent sous le pot de fleurs." },
      { if: { has: "wr:publie" }, text: "Sur la table de travail de Victorine Davrigny, il y a une pierre du Quai-aux-Harengs, à côté de l'encrier. Elle sert de presse-papiers à ses rapports. On ne lui en jette plus guère. Elle le regrette un peu." },
      { if: { all: [{ has: "wr:baron" }, { not: { has: "xs:baron_mort" } }] }, text: "Dans le coffre de la Banque Clavières, entre les titres et les créances, il y a un rapport sur une fontaine, écrit d'une petite écriture serrée de praticienne. Le baron ne s'en est jamais servi. Il le sort, quelquefois, pour le relire. Il dit que c'est le seul document de son coffre qui ait sauvé quelqu'un." },
      { if: { has: "wr:lettre" }, text: "À Morlenc, on a refait, une année, le conduit de la fontaine du Quai-aux-Harengs, et l'échevinage a fait graver sur la plaque, sous les remerciements à la Banque, une ligne de plus : « Et à une médecin de Varnèse. » Personne ne sait plus de qui il s'agit." },
      { if: { has: "ws:voilier" }, text: "Gwénolé Trébaol, voilier, a cousu des voiles assis jusqu'à quatre-vingts ans, sur une jambe de bois, en appelant à voix haute « ma sauveuse » une femme qui n'était pas là. Dans le carnet de cette femme, il y a le nom d'un garçon de dix-sept ans, écrit très appuyé." },
      { if: { has: "ws:garcon" }, text: "Un homme à la voix rauque, à demi soufflée, une voix de vieux depuis ses dix-sept ans, est devenu à Morlenc un aide-chirurgien très recherché. Il ne parle presque pas. Il a les mains les plus sûres de la ville." },
      { if: { has: "ws:mourant" }, text: "Victorine Davrigny a enseigné, plus tard, à de jeunes chirurgiens, l'ordre dans lequel on soigne les blessés, quand ils arrivent ensemble. Elle l'enseigne très bien, très froidement. Elle ajoute, à la fin, que le jour où ils ne pourront pas l'appliquer, elle espère qu'ils lui pardonneront." },
      { if: { has: "wt:rend" }, text: "Au bureau des vivres de l'Amirauté, à Morlenc, un petit commis chauve a porté le même manteau à col de loutre pendant vingt ans. Il le brosse tous les matins. Il ne rentre jamais par la rue des Cordiers." },
      { if: { has: "wt:achete" }, text: "Anatole Picot, commis aux vivres, est mort persuadé que l'Amirauté s'était un jour souvenue de lui. On l'a enterré dans un manteau bleu à col de lapin, comme il l'avait demandé, avec le mot qui l'accompagnait, glissé dans la poche." },
      { if: { has: "wt:laisse" }, text: "On dit, à la Basse-Fosse, qu'il ne faut pas porter de col de loutre rue des Cordiers, les nuits de froid. On ne sait plus pourquoi. On ne le fait pas." },
      { if: { has: "wu:tir" }, text: "Au Muséum de Morlenc, dans une vitrine, un grand oiseau gris se tient debout, le bec crochu, l'air d'un évêque en colère, à côté de son squelette. La plaque porte un nom latin et celui du professeur Gaudrémont. L'Académie s'est excusée. Le professeur n'est jamais retourné voir la vitrine." },
      { if: { has: "wu:effraie" }, text: "On n'a jamais retrouvé, sur la Table de Folle-Aiguille, ni l'oiseau gris ni ses os. Le professeur Gaudrémont n'en a jamais parlé à l'Académie. Il en a parlé une fois à quelqu'un, très tard, en disant que c'était peut-être un rêve, et que tu l'avais fait avec lui." },
      { if: { has: "wu:dessin" }, text: "Les dessins du professeur Gaudrémont, avec leurs taches entourées au crayon, sont conservés à l'Académie de Morlenc, qui a fini par les croire. On les montre aux étudiants. On ne leur dit pas ce que sont les taches. Les plus fins le devinent." },
      { if: { has: "wv:aveu" }, text: "Au camp de la cascade, une petite fille aux yeux gris pâle a grandi entre deux adultes qui ne se parlaient pas et qui l'aimaient tous les deux. On ne porte plus de lanière rouge, au camp, depuis. Personne n'a aboli la sentence. On a seulement cessé d'en teindre." },
      { if: { has: "wv:secret" }, text: "Victorine Davrigny a soigné, plus tard, beaucoup d'hommes qui portaient la main à leur poitrine sans avoir rien au cœur. Elle leur donne de l'onguent. Elle sait que ça ne sert à rien. Elle sait aussi qu'ils ne viennent pas pour ça." },
      { if: { has: "wv:maela" }, text: "Au camp de la cascade, une femme aux cheveux noirs porte encore au bras une lanière rouge, qu'elle reteint elle-même chaque printemps, avec soin, d'un rouge vif. On dit qu'elle est la plus fière du camp. On a raison." },
      { if: { has: "ww:rend" }, text: "Job Kerbrat, aide-cuisinier, a gardé toute sa vie trois piastres qu'une femme médecin avait refusées. Il les a léguées à sa petite-fille, avec une montre en argent qu'on lui avait rendue, à sa grande surprise, des années plus tard, réparée, par la poste." },
      { if: { has: "ww:garde" }, text: "Les hommes de la garnison de la Miséricorde ne parlent pas du sac jeté du haut de l'éperon, côté nord. Quand l'un d'eux en parle, après boire, les autres quittent la table." },
      { if: { has: "ww:porte" }, text: "On raconte, chez les anciens mutins de la Cormorane, qu'une femme a descendu un jour, au milieu d'un siège, le corps d'un des leurs, à travers les deux camps, et que toute une plage s'est découverte. Ceux qui y étaient ne le racontent pas. Ils ôtent leur bonnet quand on le raconte." },
      { if: { has: "wx:explique" }, text: "Tu ne te justifies jamais. Jamais. On te le reproche. On dit que tu as l'air coupable de tout, à force. Tu laisses dire. Tu as appris, un jeudi, sur la route de Varnèse, ce que valent les explications." },
      { if: { has: "wx:pere" }, text: "Le bourrelier Malandre a fermé son atelier de Varnèse quelques mois plus tard et il est parti vivre chez une de ses filles, très loin. Il n'a jamais dit pourquoi. Tu as fini par savoir ce que ton père lui avait rappelé, ce jour-là. Tu ne l'as dit à personne." },
      { if: { has: "wx:tait" }, text: "Une marchande de fil du marché de Varnèse, très vieille, t'a donné un jour un sucre d'orge, en te disant qu'elle te devait celui-là depuis longtemps. Tu l'as remerciée. Tu as su exactement duquel elle parlait." },
      { if: { has: "wy:temoin" }, text: "Le professeur Gaudrémont a porté jusqu'à sa mort un chapeau de banquier, trop grand, qui lui tombait sur les oreilles. Il disait qu'il l'avait gagné en duel. C'était à peu près vrai." },
      { if: { all: [{ has: "wy:poudre" }, { not: { has: "xs:baron_mort" } }] }, text: "Le baron Clavières porte sur lui, dans une petite bourse de cuir, deux balles de pistolet qui n'ont jamais été tirées. Il ne dit à personne d'où elles viennent. Il les fait sauter dans sa main, à la Bourse, quand il hésite." },
      { if: { has: "wy:capitaine" }, text: "La capitaine Ribaud racontait volontiers, à la retraite, qu'elle avait mis aux fers, une nuit, un baron et un académicien, et qu'ils en étaient sortis amis. Elle disait que c'était la seule négociation de sa vie qu'elle eût menée sans un mot." },
      { if: { has: "wz:poste" }, text: "Au bureau de la poste du port de Morlenc, on brûle à la fin de chaque année un petit sac gris. Tu sais ce qu'il y a dedans. Tu ne passes jamais devant le bureau la dernière semaine de décembre." },
      { if: { has: "wz:cherche" }, text: "Un facteur rural des environs de Morlenc a remis un jour, à un vieux qui fumait la pipe, avec un chien noir à tache blanche, une lettre sans nom de village. Le vieux ne savait pas lire. Il a attelé sa charrette le soir même. On ne sait pas s'il est arrivé à temps. On sait qu'il est parti." },
      { if: { has: "wz:maitre" }, text: "Tu as gardé, toute ta vie, un patron de soulier gris plié en huit, avec quatre mots appuyés au crayon. Tu n'as jamais battu personne. On te trouve trop de douceur avec les apprentis. Tu ne réponds pas." },
      { if: { has: "va:ment" }, text: "Maxence de Kervégan a épousé la fille du Change, et il est devenu échevin à son tour. Il fait bouillir ses draps, dit-on, avec une manie qui amuse ses domestiques. Une femme médecin sait pourquoi. Elle ne l'a jamais dit." },
      { if: { has: "va:refuse" }, text: "Une femme médecin a perdu, un printemps, à Morlenc, une chambre, deux dîners et la considération d'un professeur. Elle disait que c'était le meilleur marché qu'elle eût jamais conclu, et elle n'a jamais précisé ce qu'elle avait acheté." },
      { if: { has: "va:dit" }, text: "On a vu, au cimetière de la Haute-Ville, sur une tombe qu'on ne fleurit pas en public, des fleurs blanches fraîches tous les jeudis, pendant des années. Le jeune homme qui les apporte a fini par devenir échevin, contre toute attente. Il ne baisse jamais les yeux devant son père." },
      { if: { has: "vb:denonce" }, text: "Herlé, élevé par les Sœurs de la Basse-Fosse, est devenu quartier-maître, puis maître d'équipage. On le dit dur avec les jeunes, et juste. Il ne frappe jamais au filin. Il garde dans son coffre un coquillage blanc, ramassé sur une plage où il n'a passé qu'une journée." },
      { if: { has: "vb:laisse" }, text: "Le rôle de la Cormorane porte, en face d'un nom, la mention « déserteur, îlot sans nom ». Tu as perdu, ce jour-là, un bon couteau à manche de corne. Tu n'en as jamais racheté d'autre." },
      { if: { has: "vb:nuit" }, text: "Herlé raconte, dans les tavernes, qu'il a été libre une nuit entière, sur une île, et qu'il a tenu jusqu'à l'aube. On se moque de lui. Il laisse rire. Toi, tu sais qu'il ne ment pas, et que c'est la chose la plus courageuse que tu lui aies vu faire." },
      { if: { has: "vc:calme" }, text: "Goustan Kermarrec a servi sur trois navires encore, sans un écart. Il prenait vingt gouttes chaque soir, jusqu'à la fin. On l'a enterré avec sa carafe, à sa demande. Elle était pleine." },
      { if: { has: "vc:veille" }, text: "Dans le poste d'équipage de la Cormorane, un quartier-maître a posé longtemps deux carafes sur sa tablette. Les mousses qui lui ont succédé ont gardé l'habitude sans savoir d'où elle venait. Une des deux carafes est toujours pleine au matin." },
      { if: { has: "vc:ecrit" }, text: "Le mémoire d'une femme médecin sur un cas de somnambulisme en mer a été jugé remarquable par la Faculté de Morlenc. Il s'arrête au neuvième jour. Le cahier de toile du dixième n'a jamais été retrouvé." },
      { if: { has: "vd:interdit" }, text: "Un aide-charpentier de Morlenc, Tudal Nédélec, a témoigné au procès de la Cormorane. Il a dit, de l'ancien maître-coq, une seule phrase, que le greffier a recopiée : « Il a empêché qu'on me tue, et il l'a fait devant tout le monde. »" },
      { if: { has: "vd:laisse" }, text: "Aucun des hommes du camp de la plage n'a jamais parlé d'un garçon nommé Nédélec. Sa mère, à Morlenc, a attendu sa solde pendant des années. Elle a fini par recevoir, sans lettre, une bourse qui en contenait beaucoup plus. Elle n'a jamais su de qui." },
      { if: { has: "vd:previent" }, text: "Une vieille femme de la Basse-Fosse garde sur sa cheminée un couteau de cuisine qui n'est pas celui de son fils. Son fils dit qu'il le doit à un cuisinier, et qu'il le lui rendra un jour. Il ne l'a jamais retrouvé." },
      { if: { has: "ve:dit" }, text: "Ninon Kerfriden, de Varnèse, s'est remariée à quarante ans avec un maître de poste. Elle porte des gants en toute saison. Elle n'a jamais voulu d'un bijou, même en verre." },
      { if: { has: "ve:tait" }, text: "Une blanchisseuse de Varnèse est morte très vieille, très droite, sans une dette. Elle disait à ses voisines qu'elle avait payé un jour, à elle seule, un collier de dix-huit mille livres, et qu'elle referait la même chose. Une seule personne au monde savait ce que valait ce collier. Elle s'est tue jusqu'au bout." },
      { if: { has: "ve:orsel" }, text: "Madame Orsel, femme du notaire de Varnèse, ne porte plus aucun bijou. On dit qu'elle est devenue pieuse. Une femme médecin pense qu'elle est devenue prudente, ce qui, à Varnèse, revient au même." },
      { if: { has: "vf:verite" }, text: "Une femme de Morlenc, qui a peur des chats, a reçu un jour d'un inconnu un message de six mots : son père a été long à rentrer. Elle a pleuré toute la nuit. Le lendemain, elle a dit à ses enfants qu'elle se sentait plus légère, et elle ne savait pas pourquoi." },
      { if: { has: "vf:menti" }, text: "Il t'arrive de rêver d'un vieil homme assis devant une maison sans porte, un baluchon sur les genoux, qui regarde un sentier. Dans le rêve, tu marches vers lui pour tout lui dire. Tu te réveilles toujours avant d'arriver." },
      { if: { has: "vf:ecorce" }, text: "Tu ne supportes pas qu'on te dise « ça ne fait plus mal ». Tu as appris, dans un verger, ce qu'il en coûte d'avoir mal moins vite, et ce qu'il en coûte de ne plus avoir mal du tout." },
      { if: { has: "vg:signe" }, text: "Le lieutenant Kerdoncuff est mort à l'asile de Morlenc, très calme, entouré de livres. Une femme médecin a demandé à voir son dossier. Il contenait un seul certificat, d'une écriture qu'elle connaissait bien." },
      { if: { has: "vg:sain" }, text: "Un rapport cousu de fil rouge, en provenance de Brisegrève, est arrivé un jour à l'Amirauté par un chemin que personne n'a su retracer. Le gouverneur Lebihan a été rappelé. On l'a nommé ailleurs, avec un avancement. Le lieutenant du bastion a été libéré. Il a écrit une lettre de remerciement de douze pages." },
      { if: { has: "vg:parle" }, text: "Une femme médecin ne ferme jamais une porte à clef derrière un malade. On le lui reproche à l'hôpital. Elle répond qu'elle a passé, une fois, trois heures du mauvais côté d'une porte, et qu'on ne guérit personne de ce côté-là." },
      { if: { has: "vh:engage" }, text: "Josse Le Ruyet, roulier, inscrit au rôle de la Cormorane comme novice terrien, a tenu sa parole jusqu'au bout : il a attendu. Ceux qui l'ont connu disent qu'il n'a jamais rien fait d'autre de sa vie avec autant de soin." },
      { if: { has: "vh:refuse" }, text: "On montre encore, aux moulins Clavières, l'endroit où était le péage. On n'en a jamais reconstruit. Les charretiers passent sans payer, et certains, en passant, ôtent leur casquette, sans très bien savoir pour qui." },
      { if: { has: "vh:paie" }, text: "Un homme en blouse bleue s'est tenu debout, chaque jour, pendant deux ans, devant la barrière des moulins Clavières, avec un cheval boiteux. Le jour où le cheval est mort, l'intendant est sorti, a ôté son chapeau, et a dit devant tout le monde qu'on avait eu tort. Le roulier est rentré chez lui. On ne l'a plus revu au péage." },
      { if: { has: "vi:plaide" }, text: "Enora Le Ny, de Lannoz, a toujours souri quand son mari lui expliquait le monde. Elle a tenu ses comptes, en secret, jusqu'à sa mort, et elle a laissé à sa fille un cahier où tout était noté, sou par sou, avec, sur la première page : « Pour que tu saches ce que vaut un secret. »" },
      { if: { has: "vi:defie" }, text: "La femme du maître de port de Lannoz a ouvert, quelques années plus tard, une école de filles dans la seule maison de l'île qui ait un étage. Son mari l'a laissée faire. Il dit à qui veut l'entendre que c'était son idée." },
      { if: { has: "vi:temoin" }, text: "Gildas Le Ny, maître de port de Lannoz, a fait installer dans son salon un fauteuil près du poêle, où personne ne s'assied. Il dit qu'il est pour le médecin. Sa femme sourit chaque fois qu'il le dit." },
      { if: { has: "vi:seuls" }, text: "Une femme de Lannoz est rentrée chez son mari au bout de quarante jours. Elle a posé ses conditions sur la table de la cuisine, par écrit, de sa main. Il les a signées. On dit dans l'île que c'est la première signature de la maison qui soit parfaitement authentique." },
      { if: { has: "vj:dit" }, text: "Le moulin de la falaise tourne encore le dimanche, au-dessus de la grève de Varnèse. Le père Gléau est mort, on y a mis un jeune homme que paie le meunier Rannou, et qui graisse l'arbre chaque samedi pour un moulin qui ne moud rien. Les pêcheurs rentrent toujours sur lui." },
      { if: { has: "vj:tait" }, text: "Quand tu es revenu{e} à Varnèse, les ailes du moulin de la falaise ne tournaient plus. Il restait, derrière la porte, une rangée de cruches de cidre bouchées, et une boîte en fer-blanc vide. Tu as payé la pierre du vieil homme. Tu as fait graver, sous son nom : *Il a tenu.*" },
      { if: { has: "vj:lui" }, text: "Tu gardes, dans un petit sac de toile, une poignée de farine d'orge grossière, mal moulue, grise. Elle n'est bonne à rien. C'est la dernière farine du moulin de la falaise. Tu l'as vue sortir de la meule, un soir, avec un bruit de tonnerre." },
      { if: { has: "vk:dit" }, text: "Douze hommes de l'Avenante ont été pendus à Morlenc, à la Croix-des-Marées. Leur maître d'équipage, un rouquin nommé Rozec, a ôté sa chemise sur l'échafaud, devant la foule, et s'est tourné pour montrer son dos. On a dit qu'il était mort sans rien dire. C'était inutile." },
      { if: { has: "vk:billet" }, text: "Tu gardes, dans une boîte, un billet de trois mots, d'une écriture tremblée. Tu as cherché, des années plus tard, l'Avenante dans les registres du port de Morlenc. Elle y est entrée, un automne, avec onze hommes et sans capitaine. Le registre porte, en face de son nom : *mort en mer, de maladie.*" },
      { if: { has: "vk:tait" }, text: "Tu ne jettes jamais un papier sans l'avoir lu. Jamais. Même les réclames, même les billets doux des autres. On s'en moque. Tu laisses dire." },
      { if: { has: "vl:dit" }, text: "Le gouverneur Lebihan a raconté toute sa vie, dans les salons, l'histoire du savant qu'il avait pris pour un inspecteur. Il la racontait très bien. Il oubliait seulement de dire ce qu'il avait fait des citrons." },
      { if: { has: "vl:laisse" }, text: "Le mémoire du professeur Gaudrémont sur les lichens des îles du Couchant contient une dédicace au gouverneur de Brisegrève, « esprit éclairé, ami désintéressé de la science ». Une femme médecin, en la lisant, a ri si fort qu'on a dû lui apporter un verre d'eau." },
      { if: { has: "vl:joue" }, text: "Le professeur Gaudrémont a toujours dit qu'il avait passé à Brisegrève la journée la plus importante de sa carrière, sans jamais réussir à expliquer pourquoi. Une garnison entière le sait, elle. On boit encore à sa santé, au bourg, le jour de la Saint-Lichen, une fête qu'on a inventée pour lui." },
      { if: { has: "vm:soeurs" }, text: "Un garçon nommé Jannic Marzin est sorti des Sœurs de la Basse-Fosse à quatorze ans, avec un métier de cordier et une écriture superbe. Il a cherché, des années, sa petite sœur, placée ailleurs. Il l'a trouvée. Il a cherché aussi un mousse qui l'avait tenu par la main, une nuit de pluie. Celui-là, il ne l'a pas trouvé." },
      { if: { has: "vm:voisine" }, text: "La mère Pennec, de la ruelle des Ramendeuses, a élevé sept enfants, dont deux qui n'étaient pas à elle, en criant du matin au soir. Aucun des sept n'a jamais su lesquels." },
      { if: { has: "vm:fanal" }, text: "Il y a au Fanal, quand tu rentres, un garçon de six ans qui t'appelle par ton prénom et une petite fille qui ne te connaît pas et qui se cache dans les jupes de Zélie. Ton père a fait monter un deuxième lit dans ta chambre. Il ne t'a pas demandé ton avis. Il savait." },
      { if: { has: "vn:casse" }, text: "On vend encore, au marché de Varnèse, des pots à beurre agrafés de fer, taillés dans les morceaux d'une grande jarre. On les appelle des « Squiban ». Ceux qui en ont un ne le vendraient pour rien au monde." },
      { if: { has: "vn:juge" }, text: "Maître Le Guellec, juge de paix de Varnèse, citait volontiers, à la fin de sa vie, l'affaire de la jarre comme le seul jugement parfait qu'il eût rendu : les deux parties en étaient sorties également mécontentes." },
      { if: { has: "vn:attend" }, text: "Maître Caradec puise toujours son huile dans une jarre à large col, la seule de la côte. Il a fini par trouver ça commode. Il ne l'a jamais avoué. Il n'a jamais payé non plus." },
      { if: { has: "chien:tue_chef" }, text: "Dans la clairière de la Sylve, sous les fougères, les os d'une grande chienne bringée blanchissent au soleil. Les chiens de la meute font un détour pour ne pas passer dessus." },
      { if: { has: "chien:epargne" }, text: "La reine bringée de la Sylve vieillit à la tête de sa meute, une oreille arrachée, une cicatrice à la gorge. Elle mène les siens loin des plages où débarquent les hommes. Elle a appris, un matin, ce que coûte un combat." },
      { if: { has: "chien:cercle" }, text: "Tu rêves souvent, des années plus tard, d'une clairière où quinze chiens sauvages se couchent autour de toi au soleil de midi. Au réveil, tu cherches toujours la main qui a fait ça. C'était la tienne." },
      { if: { has: "chien:morsure" }, text: "Tu gardes au mollet, toute ta vie, une couronne de petites cicatrices blanches, cousues par un ermite avec une aiguille de pêcheur. Quand on te demande d'où elles viennent, tu dis : d'un chien qui n'était pas le mien." },
      { if: { all: [{ has: "chien:revenu" }, { not: { has: "chien:morsure" } }] }, text: "Il a suffi d'une voix, un matin, au bord d'une clairière, pour qu'un chien laisse une meute entière derrière lui. Tu n'as jamais su ce qu'il y avait dans cette voix. Lui le savait." },
      { if: { has: "chien:malandain_mordu" }, text: "Malandain porte jusqu'à la fin de ses jours, à l'épaule gauche, la marque d'une seule morsure, nette, profonde, donnée par un chien qui aurait pu viser plus haut." },
      { if: { has: "chien:apprivoise" }, text: "On parle encore, dans les fosses de la Basse-Fosse, du chien gris aux yeux jaunes qu'un enfant a sorti de là sans le battre. La veuve Rance n'a jamais retrouvé un chien pareil. Elle n'en cherche plus." },
      { if: { any: [{ has: "xt:vue" }, { has: "xt:gaudremont_sauve" }, { has: "xt:gaudremont_haut" }] }, text: "Sur les cartes de l'Amirauté, la Table de Folle-Aiguille porte désormais une petite mention, d'une écriture de graveur : « Faune singulière. » C'est tout ce que la marine a accepté d'écrire." },
      { if: { has: "xt:rivelin_enterre" }, text: "Une petite toile de Toussaint Rivelin, peintre de marine, de Morlenc, rue des Tanneurs, passe en vente l'année suivante, chez un brocanteur du port. Une femme à sa fenêtre. Les yeux sont gris. Le brocanteur la vend pour le cadre." },
      { if: { item: "carnet_rivelin" }, text: "Le carnet de Toussaint Rivelin est relié à neuf, et ses planches gravées sous le nom de leur auteur. L'Académie se dispute sur les bêtes. Personne ne se dispute sur la femme à la fenêtre." },
      { if: { all: [{ has: "xt:cou_vu" }, { not: { has: "gaudremont:reste" } }] }, text: "Le professeur Gaudrémont refuse jusqu'à sa mort de décrire en séance la bête de l'étang. On le presse. Il dit qu'il ne l'a pas dessinée, et qu'il ne décrit que ce qu'il a dessiné. C'est un mensonge. C'est le seul de sa carrière." },
      { if: { item: "griffe_aile" }, text: "La griffe ramassée dans le cratère aux ailes finit sous une cloche de verre, au cabinet d'histoire naturelle de Morlenc, avec une étiquette où l'on a laissé le nom en blanc." },
      { if: { has: "xs:soazig_maison" }, text: "Sur une paroi de la grotte derrière la cascade, il y a une maison dessinée au charbon, avec une porte qui ferme des deux côtés, et une plume noire sur le toit. Soazig la montre à tous ceux qui passent. Personne ne passe." },
      { if: { item: "instructions_fiacre" }, text: "Les instructions du Saint-Fiacre, au cachet recollé, finissent dans le dossier d'un procureur de Morlenc, qui les lit trois fois, ferme la porte de son cabinet, et demande un congé." },
      { if: { has: "xk:clefs_aubepine" }, text: "Au Haut-Verger, au pied d'un figuier, pousse une aubépine qu'une vieille femme a plantée sur trois clefs de fer. Elle fleurit en mai. Les gens du verger en font des couronnes, et se piquent les doigts, et ne savent pas pourquoi ils aiment ça." },
      { if: { has: "xk:clefs_rendues" }, text: "Trois clefs de fer pendent à un clou, au-dessus d'un lit vide, dans une hutte de la Sylve que la forêt reprend. Personne n'ose les décrocher." },
      { if: { has: "xk:clefs_mer" }, text: "Entre deux rochers, au bout de Folle-Aiguille, sous l'écume, trois clefs de fer rouillent sur un anneau. Les crabes y ont fait leur maison. Elles n'ouvrent plus rien, ce qui est une manière d'être pardonnées." },
      { if: { item: "clefs_chapelle" }, text: "Les clefs de la chapelle de la Miséricorde sont dans un tiroir, chez l'enfant du Fanal, avec des billes et un vieux couteau. Il arrive qu'on les sorte, la nuit, et qu'on les tienne, sans savoir quoi en faire." },
      { if: { item: "larme_ciel" }, text: "Une larme de verre noir, ramassée dans une mare de l'Écueil-Rouge, finit au bout d'un lacet, au cou de l'enfant du Fanal. Elle reste froide, été comme hiver. On la touche, quand on a trop chaud, ou trop peur." },
      { if: { has: "ecueil:etoiles" }, text: "Chaque année, à la même lune, l'enfant du Fanal se couche sur le dos, dans l'herbe, où que ce soit, et compte les étoiles qui tombent, à voix basse, pour quelqu'un qui ne les voit plus." },
      { if: { has: "xp:anselme" }, text: "Sur l'Écueil-Rouge, derrière une maison de pierres sèches, il y a deux croix maintenant. Celle d'Anselme, et une autre, plus récente, sans nom, qu'un moine aveugle a plantée pour le pêcheur de la barque, dont il n'a jamais su le nom." },
      { if: { has: "brise:biscuit" }, text: "Sur l'escalier des forçats de Brisegrève, un garçon aux yeux verts compte les marches tous les matins avec les autres. Il a eu, un jour, la moitié d'un biscuit de mer. Il en parle encore. On ne le croit pas." },
      { if: { item: "lettre_forcat" }, text: "À Plouvenec, rue du Lavoir, la veuve Le Gall reçoit une lettre de son fils, sortie d'une bouteille, des mois après qu'il l'a écrite. Elle ne sait pas lire. Le petit, qui sait, la lui lit. Il apprend que son frère est soldat." },
      { if: { has: "brise:infirmerie" }, text: "Le chirurgien-major de Brisegrève écrit à Varnèse tous les trois mois, des lettres longues, appliquées, pleines de questions. Il ne boit plus que le dimanche. À l'infirmerie du fort, on ouvre les soupiraux." },
      { if: { has: "lannoz:veillee" }, text: "Il arrive à l'enfant du Fanal, des années plus tard, de chanter à voix basse, sans le vouloir, un refrain dans une langue jamais apprise, en regardant la mer. Un seul mot. « Reviens. »" },
      { if: { has: "lannoz:tourbe" }, text: "Dans une tourbière de Lannoz, sous une brique de tourbe remise en place, un homme à la barbe rousse dort toujours, une corde de cuir au cou, d'avant les églises. On creuse ailleurs. Il ne demande plus l'heure à personne." },
      { if: { has: "lannoz:naissance" }, text: "À Lannoz, dans une maison de pierres sèches, une petite fille grandit avec un nom qui sonne comme une cloche, avec l'accent du pays. Elle est furieuse de tout, toujours, comme le premier jour. On dit qu'elle sera sage-femme." },
      { if: { has: "lannoz:mort_nee" }, text: "À Lannoz, au cimetière marin, à côté du capitaine Bréhat, il y a une toute petite tombe, sans nom, avec un galet blanc. Une femme y va le dimanche. Elle a eu trois enfants depuis. Elle y va quand même." },
      { if: { has: "xd:charte" }, text: "Quelqu'un, à Morlenc, recopie de mémoire la charte de la Compagnie de la Miséricorde, les six articles et le septième, avec le décompte des voix, et l'affiche à la porte de l'hôtel de ville. On l'arrache le lendemain. On la remet. On l'arrache. Cela dure un hiver." },
      { if: { item: "calice_compagnie" }, text: "Le calice sauvé du creuset des Puits, avec son ancre et sa croix, est posé sur l'autel de la petite église du Fanal. Le curé y dit la messe. Il ne sait pas d'où il vient. Il le trouve lourd." },
      { if: { has: "xd:liseron" }, text: "Au Haut-Verger, chaque matin, un homme maigre monte jusqu'au bassin de la source avec des fleurs. Ses mains se souviennent. Elles sont plus lentes que sa tête, et plus fidèles." },
      { if: { has: "xd:soleil_dit" }, text: "Aux Puits, les enfants pâles se racontent, le soir, une histoire qu'on leur a apportée d'en haut : le soleil monte tout seul, personne ne le pousse. Ils n'y croient qu'à moitié. C'est leur histoire préférée." },
      { if: { has: "freville:barre" }, text: "Abel Fréville, le charpentier, garde sa barre de fer dans son coffre jusqu'à la fin de ses jours, avec un nœud de ruban rouge autour. Il dit qu'elle a servi à quelque chose, une fois. Il ne dit pas à quoi." },
      { if: { has: "calixte:aveugle" }, text: "Frère Calixte, à l'Écueil-Rouge, perd la vue tout à fait l'hiver suivant. Il continue d'observer le ciel, la nuit, sur sa terrasse, en se faisant dicter les étoiles par un novice qui confond Vénus et un phare." },
      { if: { has: "xp:conseil" }, text: "Le conseil du vieux moine de l'Écueil-Rouge s'est révélé juste, comme presque tous les conseils qu'on n'écoute pas." },
      { if: { all: [{ has: "xe:sauves" }, { has: "florian:preuve" }] }, text: "Florian d'Escalis rentre à Morlenc pour la Saint-Jean, avec une page de registre et un témoin à moustache. Le procès dure un an. L'oncle Gonzague finit dans une maison de campagne très loin, avec une pension, et ne donne plus de soupers. Mathurine a sa chambre au premier, maintenant, avec une fenêtre sur la cour." },
      { if: { all: [{ has: "xe:sauves" }, { not: { has: "florian:preuve" } }] }, text: "Florian d'Escalis rentre à Morlenc pour la Saint-Jean, sans preuve, avec un proscrit pour témoin, ce qui revient à ne pas en avoir. Il plaide quand même. Il perd. Il ne s'en remet pas, et se remet à boire, et l'on dit dans la Haute-Ville que son oncle avait bien raison." },
      { if: { all: [{ not: { has: "xe:sauves" } }, { any: [{ has: "florian:oncle" }, { has: "florian:ignore" }] }] }, text: "Florian, le jeune homme qu'on avait enlevé sur le quai des Hollandes, n'a jamais revu Morlenc. Son oncle a hérité. L'oncle est échevin. On lui a donné une médaille." },
      { if: { has: "malbosc:enfui" }, text: "Malbosc, le Sanglier, a disparu dans les tourbières de Lannoz. On dit qu'il y vit encore, qu'il chante des chansons indécentes aux douaniers, et qu'il ne paie pas l'impôt. C'est presque un saint, dans la région." },
      { if: { has: "xe:laisses" }, text: "Les deux fugitifs de Lannoz que Victorine a soignés et laissés dans la bergerie, avec de l'eau et du pain, ont gagné la montagne. L'un d'eux lui écrit, des années plus tard, une lettre sans signature. Elle la garde dans sa trousse." },
      { if: { has: "xe:vendus" }, text: "Les deux fugitifs vendus au capitaine Hamon pour vingt livres ont fini aux galères de Lisse. Victorine a gardé les vingt livres dans une enveloppe, sans les dépenser. Elle ne sait pas à qui les rendre." },
      { if: { has: "benoit:plage" }, text: "Les malades qu'on avait cachés dans des sacs, sur la plage de Lannoz, se souviennent du médecin en robe grise qui s'est plantée devant le capitaine Hamon. Il y a, à Lannoz, une petite fille qui s'appelle Victorine." },
      { if: { has: "xf:libere" }, text: "Les créatures du Façonneur, libérées de leurs cages, vivent encore sur l'îlot. Les pêcheurs qui passent au large entendent, certaines nuits, une litanie lente qui monte de la forêt. Elle a changé de paroles. Elle parle d'une mère." },
      { if: { has: "xf:verite" }, text: "Sur l'îlot, la Mère raconte aux autres qu'un jour, une enfant venue de la mer lui a dit qu'elle était née d'une mère, sans le Maître. C'est devenu leur évangile." },
      { if: { has: "xf:mensonge" }, text: "Sur l'îlot, la Mère raconte qu'un jour, une enfant venue de la mer a dit que le Maître l'avait faite. Ils ont attendu le Maître longtemps. Il n'est jamais revenu." },
      { if: { has: "xf:marin_mort" }, text: "On n'a jamais retrouvé le corps du matelot de la chaloupe, sur l'îlot. Sa mère, à Varnèse, met un couvert pour lui le dimanche." },
      { if: { has: "xf_regle=personne" }, text: "Sur l'îlot, le soir, on récite une Règle d'une seule ligne : « Personne ne fait personne. » Le Dogue la récite avec les autres, en souriant. Il est le seul à l'avoir comprise jusqu'au bout, dans les deux sens." },
      { if: { has: "xf_regle=jours" }, text: "Devant chaque hutte de la clairière, il y a un tas de pierres blanches. Celui de la Mère monte jusqu'à son épaule. Elle les compte, le soir, à voix haute, et se trompe toujours, et recommence avec plaisir." },
      { if: { has: "xf_regle=aucune" }, text: "Les Pupilles de l'îlot ont fini par trouver une Règle à eux. Les pêcheurs qui l'ont entendue ne s'accordent pas sur les paroles. Ils s'accordent sur le fait qu'on n'aborde plus là-bas." },
      { if: { has: "sept:lannoz" }, text: "Sur la lande de Lannoz, une vieille femme est morte à quatre-vingt-trois ans, en laissant ses chèvres à son berger. Le berger porte un capuchon par tous les temps. Le recteur, presque aveugle, le trouve très pieux." },
      { if: { has: "sept:source" }, text: "Celui qui s'appelait Sept signe désormais « Source », en grandes lettres dont le R est toujours à l'envers. Personne n'a jamais eu le courage de le lui dire." },
      { if: { has: "sept:sauveur" }, text: "Sauveur a sculpté une seconde tasse. Elle fuit aussi. Il dit que c'est exprès, pour que son invité ne se sente pas seul." },
      { if: { has: "xf:mere_soignee" }, text: "La Mère, sur l'îlot, montre à qui veut le voir la cicatrice sous son bras, une ligne propre, fine, la seule couture de son corps que le Maître n'a pas faite. Elle dit que c'est la plus belle." },
      { if: { has: "xf:mere_morte" }, text: "Dans le petit cimetière derrière la maison blanche, il y a une tombe de plus, au bout de la rangée. Elle n'a pas de chiffre. Les Pupilles y ont écrit, avec des coquillages, un mot de trois lettres qu'ils ont dû apprendre seuls." },
      { if: { has: "xf:opere" }, text: "Victorine Davrigny ne parle jamais de sa seconde nuit dans la salle blanche. Mais ses confrères remarquent qu'elle refuse, sans explication, toutes les opérations de la gorge. Elle dit qu'elle n'est pas assez habile. C'est la seule chose fausse qu'on l'ait entendue dire sur son métier." },
      { if: { has: "xf:dose" }, text: "Victorine garde, au fond d'un tiroir, une petite cuiller d'argent qu'elle a emportée sans le vouloir d'une salle blanche, sur un îlot des Sargues. Elle ne s'en sert pas. Elle ne la jette pas non plus." },
      { if: { has: "xf:scalpel_rendu" }, text: "Une lettre arrive un jour à Varnèse, d'une écriture superbe, au long fût. Elle ne contient qu'une ligne : « Il a dit maman. » Victorine la brûle, puis le regrette, puis se félicite de l'avoir brûlée." },
      { if: { all: [{ has: "ombeline:abord" }, { has: "ombeline:apprentie" }] }, text: "Ombeline, l'aide du Façonneur, devient à Varnèse l'élève de Victorine Davrigny, puis sa collègue. Sur la première page de chacun de ses carnets, elle écrit un seul mot : « Demander. »" },
      { if: { has: "ombeline:oublie" }, text: "Ombeline porte toujours dans sa poche la couverture vide d'un petit carnet relié de toile. Elle n'y a jamais rien réécrit. Elle la tient, quand elle a peur, comme d'autres tiennent un chapelet." },
      { if: { has: "ombeline:greffe" }, text: "Yvon Le Bihan, matelot de la Cormorane, montre dans tous les ports un doigt recousu qui plie d'un quart de pouce. Il paie ses tournées avec. Il ne sait pas qu'il porte au bout de la main la question la plus difficile de la médecine." },
      { if: { has: "ombeline:retenue" }, text: "Ombeline n'opère plus jamais seule. Quand on lui demande pourquoi, elle répond qu'elle a appris à compter jusqu'à trois, et que c'était plus difficile qu'il n'y paraît." },
      { if: { all: [{ has: "ombeline:abord" }, { not: { has: "ombeline:apprentie" } }] }, text: "Ombeline, l'aide du Façonneur, s'installe à Varnèse, et tient la maison de Victorine Davrigny. Elle soigne les chiens du quartier, et elle est très douée, d'une manière qui met tout le monde mal à l'aise." },
      { if: { has: "xf:aide" }, text: "Victorine se souvient, quelquefois, des deux heures passées à tenir l'écarteur, dans la salle blanche de l'îlot. Elle se souvient qu'elle a compris. Elle ne l'écrira jamais." },
      { if: { has: "xf:fui" }, text: "Le Façonneur, maître Évariste Hallé, est mort sur son îlot. On a retrouvé ses carnets. L'Académie de Morlenc les a mis sous clef, dans une armoire, dont personne ne sait plus où est la clef." },
      { if: { any: [{ has: "vauclair:gris_vu" }, { has: "vauclair:defaut" }] }, text: "Le jeune chirurgien Vauclair a retrouvé, dit-on, le visage d'un homme qu'on ne voit pas. Il exerce à Lisse, sous un autre nom. Ses patients le disent excellent, et un peu distrait." },
      { if: { any: [{ has: "voleur:battu" }, { has: "voleur:mordu" }, { has: "voleur:epargne" }] }, text: "Le voleur de la nuit du coffre, à Morlenc, celui de la lucarne et de la penderie, a été pendu deux ans plus tard pour un autre vol, à la Croix-des-Marées. Il a crié, en montant, qu'il avait connu les gens de la Cormorane. Personne ne l'a cru." },
      { if: { any: [{ has: "sabran:signale" }, { has: "sabran:chevalier_vu" }, { has: "sabran:chevalier_su" }] }, text: "Sabran Quéru, le Grêlé, finit capitaine. De quoi, on ne sait pas trop. Il porte toujours sa chemise de dentelle et sa dent d'or. Il ne sait toujours pas lire, et il le cache très bien." },
      { if: { has: "fargue:sait_chevalier" }, text: "Lucien Fargue savait, depuis Morlenc, que Sabran vendait l'expédition au Chevalier. Il n'a rien dit à personne. C'était sa manière de tenir les comptes : en silence, et à la fin." },
      { if: { any: [{ has: "freres:soufflet" }, { has: "freres:trahison" }, { has: "xb2:second" }] }, text: "Au bal de la Haute-Ville, on parle encore du soufflet que le Chevalier a donné à son frère, devant tout le monde. On ne parle pas de ce qui a suivi, sur l'île. Personne, à Morlenc, ne le sait." },
      { if: { has: "xi:reste" }, text: "Sur une petite plage de galets, au sud de Folle-Aiguille, il y a, à l'aube, quand la lumière est rasante, une ombre d'homme sur les galets, et personne pour la faire. Les pêcheurs qui passent au large se signent. Ceux qui accostent n'y trouvent qu'une jarre d'aloès, et une voix polie qui leur demande des nouvelles de l'Académie." },
      { if: { has: "xi:mer" }, text: "Ulysse Fenouillet, chimiste, ancien membre correspondant de l'Académie de Morlenc, rayé de ses registres pour inconduite scientifique, est entré dans la mer, à l'aube, au sud de Folle-Aiguille. On ne retrouvera pas le corps. On ne l'a jamais trouvé non plus de son vivant." },
      { if: { has: "gaudremont:fenouillet" }, text: "Le passager qu'on ne voyait pas, Fenouillet, a écrit au professeur Gaudrémont une lettre de quarante pages, d'une encre que personne d'autre ne peut lire." },
      { if: { has: "xt:dessins" }, text: "Les dessins des lézards qui marchent debout, rapportés de la Table, sont exposés à l'Académie de Morlenc, sous une vitre, avec une étiquette qui dit « Fantaisie ». Le professeur Gaudrémont la change chaque semaine. On la remet chaque semaine." },
      { if: { has: "xt:jambe" }, text: "La jambe du professeur Gaudrémont n'a jamais été tout à fait droite. Il boite, depuis, avec ostentation, et refuse la canne. Il dit qu'on ne cache pas une preuve." },
      { if: { has: "gaudremont:ramene" }, text: "Le professeur Gaudrémont présente ses découvertes à l'Académie de Morlenc un jeudi d'avril. La séance dure six heures. Deux académiciens s'évanouissent, un troisième démissionne. Le professeur est élu président l'année suivante, à une voix, la sienne, qu'il a eu la décence de ne pas s'accorder, et qu'on lui a accordée par erreur." },
      { if: { has: "gaudremont:reste" }, text: "Le professeur Gaudrémont n'est jamais rentré. Un baleinier, dix ans plus tard, a vu sur la Table, au loin, un homme à barbe blanche qui courait derrière des oiseaux plus grands que lui." },
      { if: { any: [{ has: "xd:machee" }, { has: "xd:visite" }, { has: "xd:sauveur_vu" }] }, text: "Au Haut-Verger, les Doux continuent de vivre comme avant, dans les vergers, sous les arbres. Ils mâchent l'écorce douce, ils chantent sans paroles, ils oublient vite. Ils oublient les gens de la mer en une saison. Ils se souviennent, inexplicablement, d'un enfant." },
      { if: { has: "xs:guerre" }, text: "Jeanne Brasdefer et ses proscrits sont restés dans la Sylve, avec leur haine, leurs arcs et leurs plumes noires. On dit qu'ils guettent encore la mer. Ils attendent un navire du baron. Il n'en viendra plus." },
      { if: { has: "xs:baron_livre" }, text: "Jeanne Brasdefer a eu le baron, comme elle voulait. Elle ne s'en est pas trouvée mieux. Elle l'a dit à Victorine, la dernière fois, avec étonnement." },
      { if: { has: "xs:baron_sait" }, text: "Le baron savait, depuis la lettre de Jeanne, ce qu'il avait laissé sur l'île avec le Saint-Fiacre. Il n'a jamais rien dit. Il gardait les comptes, lui aussi, en silence." },
      { if: { has: "mutins:abandonnes" }, text: "Les mutins laissés sur la plage de l'Anse-Morte ont fondé un village, au bout de dix ans. Ils ont des femmes du Haut-Verger, des enfants, des chèvres. Ils racontent qu'ils ont choisi de rester. Ils finissent par le croire." },
      { if: { has: "mutins:egares" }, text: "Le mutin qui s'était enfoncé jusqu'au genou dans une marmite de boue bouillante, dans les collines du nord, n'a plus jamais marché droit. Il raconte à qui veut l'entendre qu'un enfant l'a égaré exprès. On le croit. Ça fait une bonne histoire." },
      { if: { has: "malandain:haine" }, text: "Malandain a juré, sous la terre, de retrouver un jour l'enfant qui a brûlé le livre. Il n'en a pas eu le temps." },
      { if: { has: "malandain:fondeurs" }, text: "Les Fondeurs ont enterré Malandain au fond d'une galerie, avec ses lingots, parce qu'il les aimait. Ils ont refermé la galerie. Ils sont pratiques, les Fondeurs, et pas sans humour." },
      { if: { has: "autel:ouvert" }, text: "Sur l'autel de la Miséricorde, on a remis la dalle, et sur la dalle, un calice d'argent tordu, écrasé, qu'on a redressé comme on a pu." },
      { if: { has: "cormorane:renflouee" }, text: "La Cormorane, déséchouée de l'Anse-Morte, navigue encore vingt ans. Elle a gardé de son échouage une gîte légère sur bâbord, qu'on n'a jamais pu corriger. Les marins l'appellent la Boiteuse, avec affection." },
      { if: { any: [{ has: "desinvolte:apaisee" }, { has: "desinvolte:partie" }] }, text: "La Désinvolte est repartie de l'Anse-Morte sans rien. Le Chevalier n'en a jamais parlé. C'est la seule campagne de sa vie qu'il n'a pas racontée." },
      { if: { any: [{ has: "correction:appliquee" }, { has: "correction:table" }, { has: "victorine:pacte_correction" }] }, text: "La correction de l'aiguille, trois quarts au couchant, est inscrite depuis dans les instructions nautiques de l'Amirauté de Morlenc, à la page de Folle-Aiguille, sans nom d'auteur." },
      { if: { has: "xk:signes" }, text: "Le parchemin de Larrouy, déchiffré signe à signe dans la cambuse de la Cormorane, est resté dans les affaires de {joueur}, plié en huit. On le ressort quelquefois, pour le relire, et pour sentir l'odeur de l'oignon." },
      { if: { has: "chien:abord" }, text: "La capitaine Ribaud n'a jamais reconnu avoir eu tort à propos du chien. Elle lui donne, le soir, dans sa cabine, les restes de son assiette, quand elle croit que personne ne la voit." },
      { if: { has: "victorine:benoit" }, text: "Benoît Quémeneur a gardé, de la traversée, l'habitude de faire le tour de l'horizon à la longue-vue, chaque matin, en silence, et de passer la lunette à quelqu'un, sans rien dire." },
      { if: { has: "victorine:rameur_mort" }, text: "Victorine pense quelquefois au matelot de la yole, celui de l'artère, sous ses paumes, quatre minutes. Elle pense qu'il lui en aurait fallu cinq. Elle y pense moins, avec les années, et elle s'en veut d'y penser moins." },
      { if: { any: [{ has: "m2v:defaut" }, { has: "m5b:defaut" }, { has: "v5b:defaut" }] }, text: "Il y a, dans cette histoire, des jours qu'on n'a pas vus de près, et qui se sont passés quand même, comme se passent les jours des autres : sans nous, et pourtant à cause de nous." },
      { if: { has: "mousse:marche_fargue" }, text: "Le marché passé au rocher qui sonne, l'argent contre la vie des autres, a tenu. Les marchés les plus mauvais tiennent souvent mieux que les autres." },
    ],
    fates: [
      { who: "mousse", label: "L'enfant du Fanal", list: [
        { id: "pirate", title: "L'enfant, sous pavillon noir", dens: "mutins", if: { has: "mutins:navire" },
          text: "**{joueur}** navigue dix ans avec le maître-coq, sur des mers dont on ne revient pas toujours. On l'appelle le Mousse jusqu'à trente ans. Un jour, sur une île du Sud, {joueur} descend à terre et ne remonte pas à bord. On dit qu'il y a là-bas une auberge, au bord d'une falaise, avec un volet où l'on n'a jamais rien cloué." },
        { id: "fanal", title: "L'enfant, au Fanal", dens: RENTRE, if: { all: [{ any: [{ has: "livre=brule" }, { has: "victorine:ligne_hersant" }] }] },
          text: "**{joueur}** rentre au Fanal par la diligence de Varnèse, puis à pied. Lazare Hersant est derrière son comptoir, il essuie des verres. Il lève les yeux. Il ne dit rien. {joueur} non plus. Ils restent comme ça un long moment. Puis {joueur} dit : « Un quart de part. » Et son père pose le verre, et s'assied, et se met à parler, pour la première fois, jusqu'au matin." },
        { id: "ecrivain", title: "L'enfant qui écrit", dens: RENTRE, if: { voie: "ecrivain" },
          text: "**{joueur}** écrit l'histoire de Folle-Aiguille, des années plus tard, à la table de la salle du Fanal, la nuit, quand les clients sont partis. On la publie à Morlenc sous un faux nom. On la trouve invraisemblable. On l'achète beaucoup." },
        { id: "colon", title: "L'enfant de l'île", dens: "naufrage", if: { has: "fin:naufrage" },
          text: "**{joueur}** reste sur Folle-Aiguille quand le baleinier repart. Avec le chien, s'il est là, et un briquet, et un carnet. On l'appelle, chez les Doux, l'enfant qui écrit. Chez les Fondeurs, l'enfant qui a vu le mur. C'est assez pour une vie. C'est même beaucoup." },
        { id: "marin", title: "L'enfant, marin", dens: RENTRE, if: { has: "navire:ok" },
          text: "**{joueur}** rembarque au printemps sur la Cormorane, avec la capitaine Ribaud, comme matelot, puis comme second, à vingt-cinq ans. Le soir, au quart, {joueur} regarde l'aiguille du compas, et sourit, et ne dit pas pourquoi." },
        { id: "rentre", title: "L'enfant, de retour",
          text: "**{joueur}** rentre au Fanal, un jour, par le chemin de la falaise, en boitant un peu, d'une vieille blessure de l'île. Lazare l'attend sur le seuil. Zélie pleure dans la cuisine. On ne raconte rien, le premier soir. On a le temps." },
      ] },
      { who: "victorine", label: "Victorine Davrigny", list: [
        { id: "hospice", title: "Victorine, l'hospice", dens: "livre", if: { has: "fin:livre" },
          text: "**Victorine Davrigny** dirige l'hospice de Varnèse, bâti avec l'argent de la Miséricorde. La Faculté de Morlenc lui offre une chaire, quand l'histoire de son diplôme se répand. Elle la refuse, par lettre, en trois lignes, dont une est très grossière." },
        { id: "quitte", title: "Victorine, quitte", dens: ["baron", "ile", "chevalier"], if: { has: "victorine:dettes_remises" },
          text: "**Victorine Davrigny** rentre à Varnèse quitte de ses dettes, pour la première fois depuis Hector. Elle s'achète un cheval, un vrai, et une pipe d'écume. Elle reprend la sonnette de nuit, et les pêcheurs qui toussent. Elle se demande, quelquefois, à quel prix elle a été libérée, et elle trouve toujours la même réponse, et elle reprend sa pipe." },
        { id: "ile", title: "Victorine, médecin de l'île", dens: "naufrage", if: { has: "fin:naufrage" },
          text: "**Victorine Davrigny** reste sur Folle-Aiguille. Elle soigne les Doux, les Fondeurs, les marins, les proscrits. Elle n'a jamais eu autant de malades, ni si peu de factures. Elle meurt très vieille, sous les orangers de la Miséricorde, dans un fauteuil de bambou, avec une pipe éteinte à la main." },
        { id: "noms", title: "Victorine, les six noms", if: { has: "victorine:noms_macons" },
          text: "**Victorine Davrigny** fait graver, à ses frais, sur une plaque de cuivre, au fronton de la chapelle de Varnèse, six noms de maçons qu'elle a recopiés sur un mur, sous une colline. Personne ne sait qui ils sont. On lui demande. Elle répond : « Des gens qu'on a comptés. »" },
        { id: "varnese", title: "Victorine, à Varnèse",
          text: "**Victorine Davrigny** reprend son cabinet de la rue des Cordiers, à Varnèse, et la sonnette de nuit, et les pêcheurs qui toussent. Elle ne parle jamais de l'île. Le soir, quelquefois, elle sort son carnet de l'expédition, le relit, et le range, et va se coucher de meilleure humeur, sans savoir pourquoi." },
      ] },
      { who: "fargue", label: "Lucien Fargue", list: [
        { id: "capitaine", title: "La Chanson, capitaine", dens: "mutins", if: { has: "fin:mutins" },
          text: "**Lucien Fargue** commande la Cormorane sous pavillon noir pendant six ans. Il fait envoyer, chaque année, par des voies obscures, de l'argent aux sœurs de la Basse-Fosse, pour une jeune femme qui tousse. Il meurt en mer, d'une fièvre, en chantant. On dit qu'il chantait juste jusqu'au bout." },
        { id: "lisette_livre", title: "La Chanson, et Lisette", dens: RENTRE, if: { has: "livre=fargue" },
          text: "**Lucien Fargue** vend le livre de la Maraude au baron, ou à une autre des sept familles, au prix qu'il fixe. Il emmène Lisette à la montagne, dans un village où l'air est si pur qu'il fait mal. Elle guérit, à moitié. Elle ne saura jamais d'où vient l'argent. Il le lui dit, à la fin, un soir d'hiver. Elle lui répond qu'elle s'en doutait, et qu'elle l'aime quand même, ce qui est exactement ce qu'il craignait le plus d'entendre." },
        { id: "sac", title: "La Chanson, quatre lingots", if: { has: "fargue:sac" },
          text: "**Lucien Fargue** emmène Lisette à la montagne avec quatre lingots d'argent, et pas un de plus. Il ouvre une auberge, là-haut. Il fait la cuisine. Il chante le soir, pour les voyageurs. Lisette tient les comptes. Elle tousse moins." },
        { id: "retourne", title: "La Chanson, rentré", dens: RENTRE, if: { any: [{ has: "fargue:retourne" }, { has: "fargue:emmene_dagrel" }, { has: "fargue:laisse_dagrel" }] },
          text: "**Lucien Fargue** rentre à Morlenc, et va chez les sœurs de la Basse-Fosse, et s'assied au chevet de Lisette, et lui raconte tout, la Maraude, la colonie, le mur, Gildas, l'île. Ça prend trois jours. Elle l'écoute sans l'interrompre. À la fin, elle lui demande s'il sait faire le gâteau aux amandes de sa mère. Il sait." },
        { id: "ile", title: "La Chanson, sur l'île", dens: ["naufrage", "chevalier"],
          text: "**Lucien Fargue** reste sur Folle-Aiguille. Il fait la cuisine pour les Fondeurs, qui n'ont jamais si bien mangé. Il écrit à Lisette une lettre par an, qu'il confie à chaque navire qui passe. Elles arrivent toutes, dans le désordre." },
        { id: "seul", title: "La Chanson",
          text: "**Lucien Fargue** disparaît de Morlenc au printemps. On dit qu'il cuisine à bord d'un navire marchand, sur les routes du Sud, sous un autre nom. On dit qu'il chante encore. Chez les sœurs de la Basse-Fosse, une jeune femme reçoit, chaque mois, une lettre sans signature, d'une écriture qu'elle reconnaît." },
      ] },
      { who: "dagrel", label: "Jéricho Dagrel", list: [
        { id: "mort", title: "Le septième maçon", if: { has: "dagrel:mort" },
          text: "**Jéricho Dagrel** est resté sous la colline, assis entre deux maçons, comme un septième qui serait arrivé en retard à l'office. Les Fondeurs ont refermé le mur, avec une pierre gravée qui dit la même chose qu'avant." },
        { id: "pendu", title: "Le pendu de la Croix", dens: "corde", if: { has: "fin:corde" },
          text: "**Jéricho Dagrel** est pendu à la Croix-des-Marées, à soixante-trois ans, devant tout Morlenc. Il a revu la ville. Il ne s'est pas plaint." },
        { id: "morlenc", title: "Le capitaine de la Basse-Fosse", dens: "dagrel", if: { has: "fin:dagrel" },
          text: "**Jéricho Dagrel** meurt dans son lit, à Morlenc, trois ans plus tard, dans une chambre au-dessus d'un cordier, la fenêtre ouverte sur le port. Personne ne sait qui il est. C'était tout ce qu'il demandait." },
        { id: "inconnu", title: "Sauveur", if: { not: { has: "dagrel:demasque" } },
          text: "**Le vieil homme de la Sylve**, que les Doux appellent Sauveur et les Fondeurs le Vieux, continue de vivre dans sa hutte sous la Table. Il troque des fruits contre des nouvelles du monde. Personne, de l'expédition, n'a jamais su son vrai nom." },
        { id: "ile", title: "Le Vieux",
          text: "**Jéricho Dagrel** reste sur son île. Il vit dans sa hutte, sous la Table, entre les Doux et les Fondeurs. Il raconte des histoires, le soir, à qui veut l'entendre. Il dit qu'il a eu, un jour, la visite de gens de son ancienne vie, et que c'était très divertissant." },
      ] },
      { who: "claviere", label: "Le baron Clavières", list: [
        { id: "mort", title: "Le baron, mort sur l'île", if: { has: "xs:baron_mort" },
          text: "**Le baron Aymeric Clavières** repose sur Folle-Aiguille, dans une fosse creusée par des gens qu'il y avait abandonnés. Il n'y a pas de croix. Il y a une plume noire, plantée dans la terre." },
        { id: "pendu", title: "Le baron, la tringle", dens: "livre", if: { all: [{ has: "fin:livre" }, { not: { has: "baron:force" } }] },
          text: "**Le baron Aymeric Clavières** s'est pendu dans son cabinet, sous le portrait de son père, la veille de la Saint-Michel. On l'enterre à la sauvette, de nuit. Victorine Davrigny est la seule à suivre le corbillard. Elle ne sait pas pourquoi. Elle y va." },
        { id: "exil", title: "Le baron, au-delà des montagnes", dens: "livre", if: { has: "fin:livre" },
          text: "**Le baron Aymeric Clavières** vit au-delà des montagnes, sous un autre nom. Il prête de l'argent. Il en gagne. Il joue au pharaon le samedi. Il ne lit plus de livres." },
        { id: "pauvre", title: "Le baron, ruiné", dens: ["ile", "chevalier", "naufrage", "mutins"], if: BARON,
          text: "**Le baron Aymeric Clavières** perd sa banque à l'automne. Il vend l'hôtel de la Haute-Ville, la perruque, les pistolets d'ivoire. Il loue deux pièces au-dessus d'une boutique de rubans. Il dit, à qui veut l'entendre, qu'il n'a jamais si bien dormi. C'est presque vrai." },
        { id: "echevin", title: "Le baron, réélu",
          text: "**Le baron Aymeric Clavières** reste échevin, banquier, armateur, généreux en public. Sa banque se redresse. Il fait bâtir une aile neuve à l'hôpital de Morlenc, qui porte le nom de son père. Il n'y entre jamais." },
      ] },
      { who: "lazare", label: "Lazare Hersant", list: [
        { id: "parle", title: "Lazare, qui parle", if: { any: [{ has: "livre=brule" }, { has: "victorine:ligne_hersant" }, { has: "fin:livre" }] },
          text: "**Lazare Hersant**, l'aubergiste du Fanal, a parlé, un soir, pendant toute une nuit, de la Maraude, de la colonie, de la balle dans la jambe, du briquet. Depuis, il boite moins. Zélie dit que c'est l'âge. C'est autre chose." },
        { id: "attend", title: "Lazare, au Fanal",
          text: "**Lazare Hersant** essuie des verres derrière le comptoir du Fanal, en boitant. Il regarde la mer par la fenêtre de la salle, chaque soir, un peu plus longtemps qu'avant. Il ne parle toujours pas. Il attend qu'on lui pose la question." },
      ] },
      { who: "chien", label: "Le chien-loup", list: [
        { id: "meute", title: "La meute de la Miséricorde", if: { all: [{ has: "chien:apprivoise" }, { has: "chien:meute" }, { not: { has: "chien:revenu" } }] },
          text: "**Le chien-loup** reste sur Folle-Aiguille, le jour du départ. Il t'accompagne jusqu'au bord de l'eau, s'assied dans l'écume, et regarde la chaloupe s'éloigner sans un cri. Derrière lui, à la lisière, quinze chiens attendent qu'il se retourne. Il se retourne. Les marins de passage, depuis, parlent d'une meute grise qui chasse en silence et qui laisse les naufragés tranquilles." },
        { id: "ile", title: "Le loup de l'île", if: { all: [{ has: "chien:apprivoise" }, { has: "fin:naufrage" }] },
          text: "**Le chien-loup** court dans la Sylve de Folle-Aiguille, libre. Il revient le soir. Il a fait des petits, avec on ne sait quoi, qui ont les yeux jaunes et qui ne mordent que les gens qui le méritent." },
        { id: "fanal", title: "Le chien du Fanal", if: { has: "chien:apprivoise" },
          text: "**Le chien-loup** dort devant la cheminée du Fanal, l'hiver, et sur la falaise, l'été, face à la mer. Il a les yeux jaunes et le museau gris. Zélie le nourrit en grommelant. Il ne mord plus personne. Il n'en a plus besoin." },
        { id: "loin", title: "Le chien des fosses",
          text: "**Le chien gris aux yeux jaunes** des fosses de la Basse-Fosse a disparu de Morlenc. On dit qu'on l'a vu courir sur une plage, très loin, derrière quelqu'un." },
      ] },
      { who: "ribaud", label: "La capitaine Ribaud", list: [
        { id: "perdue", title: "La capitaine sans navire", if: { any: [{ has: "navire:perdu" }, { has: "mutins:partis" }, { has: "mutins:navire" }] },
          text: "**Solange Ribaud** a perdu la Cormorane. Elle ne commande plus. Elle tient une école de navigation à Morlenc, pour les fils de pêcheurs, et les filles, ce qui fait scandale. Elle leur apprend, d'abord, à se méfier des aiguilles." },
        { id: "boiteuse", title: "La capitaine de la Boiteuse", if: { has: "cormorane:renflouee" },
          text: "**Solange Ribaud** commande la Cormorane, la Boiteuse, encore douze ans. Elle a fait redresser sa gîte trois fois. Elle n'a jamais réussi. Elle a fini par l'aimer." },
        { id: "cormorane", title: "La capitaine",
          text: "**Solange Ribaud** ramène la Cormorane à Morlenc, et repart au printemps, pour un armateur honnête, ce qui existe. Elle ne parle jamais de l'île, ni du baron, ni du trésor. Elle dit seulement, quand on lui demande, qu'il faut toujours se méfier d'un cuisinier qui chante juste." },
      ] },
      { who: "gaudremont", label: "Le professeur Gaudrémont", list: [
        { id: "reste", title: "Le professeur, sur la Table", if: { has: "gaudremont:reste" },
          text: "**Hippolyte Gaudrémont** vit sur la Table de Folle-Aiguille, au milieu des bêtes qui n'existent plus. Il écrit, sur des écorces, une histoire naturelle que personne ne lira. Il est, dit-on, parfaitement heureux, et parfaitement furieux, les deux à la fois, comme toujours." },
        { id: "academie", title: "Le professeur, président", if: { any: [{ has: "gaudremont:ramene" }, { has: "xt:gaudremont_sauve" }] },
          text: "**Hippolyte Gaudrémont** devient président de l'Académie de Morlenc, et le reste douze ans, et les fait vivre à l'Académie comme un siège. Il prépare une seconde expédition à Folle-Aiguille jusqu'à sa mort. Il ne la fera pas. Il n'en avait pas besoin : il avait déjà raison." },
        { id: "rentre", title: "Le professeur",
          text: "**Hippolyte Gaudrémont** rentre à Morlenc sans preuves, et raconte. Personne ne le croit. Il raconte plus fort. On finit par le croire, à l'usure, comme on croit tous les vieillards têtus." },
      ] },
      { who: "brasdefer", label: "Jeanne Brasdefer", list: [
        { id: "tribunal", title: "Jeanne, au premier rang", dens: "livre", if: { all: [{ has: "xs:justice" }, { has: "fin:livre" }] },
          text: "**Jeanne Brasdefer** est au premier rang, sur la Croix-des-Marées, le premier vendredi du mois, comme on le lui avait promis. Elle regarde jusqu'au bout. Puis elle rentre rue des Fondeurs, rallume la forge de son père, et frappe toute la nuit, pour retrouver le son." },
        { id: "promesse", title: "Jeanne, qui attend", if: { has: "xs:justice" },
          text: "**Jeanne Brasdefer** a quitté la Sylve sur la parole d'une médecin. Elle vit à Morlenc, dans une rue où personne ne la connaît plus, et elle attend le procès qu'on lui a promis. Elle a gardé une plume noire dans sa poche. Une seule. Pour le cas où." },
        { id: "vengee", title: "Jeanne, vengée", if: { has: "xs:baron_mort" },
          text: "**Jeanne Brasdefer** n'a plus planté de plume. Elle reste dans la Sylve avec les siens, qui n'ont plus rien à jurer le soir, et qui ne savent pas quoi faire de leurs soirées. Elle dit que la vengeance, c'est comme la faim : on la croit finie, et on a encore faim." },
        { id: "sylve", title: "Jeanne, dans la Sylve",
          text: "**Jeanne Brasdefer** plante une plume noire, chaque soir, dans une fente de la grotte derrière la cascade. Il n'y a plus de place depuis longtemps. Elle en trouve." },
      ] },
      { who: "benoit", label: "Benoît Quémeneur", list: [
        { id: "parti", title: "Benoît, avec son frère", if: { has: "benoit:parti" },
          text: "**Benoît Quémeneur** est parti, une nuit, sur l'île, rejoindre son frère. Il navigue sur la Désinvolte. On dit qu'il est devenu aussi brillant que l'aîné, et aussi cruel. On dit aussi le contraire. Ceux qui l'ont connu savent que les deux sont faux." },
        { id: "reconcilies", title: "Benoît, et Alexis", if: { has: "freres:reconcilies" },
          text: "**Benoît Quémeneur** rentre à Morlenc, et dîne chez son frère, le Chevalier, le premier dimanche du mois, avec Héloïse. Ils se disputent à chaque fois. Ils reviennent à chaque fois." },
        { id: "second", title: "Benoît, le second",
          text: "**Benoît Quémeneur** reste second de la Cormorane, ou d'un autre navire. Il ne commande jamais. Il dit qu'il n'aime pas ça. Il est le seul homme du Couchant à le dire et à le penser." },
      ] },
    ],
  },
};
